************************************************************************
*                                                                      *
      subroutine tletreg(ncol,m,nl,lt,np,nr,mr,ne,kr,eb,tr,trEVENT)
*                                                                      *
*       LET tally in region mesh                                       *
*       last modified by K.Niita on 2005/08/31                         *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*      ncol  ..... reaction type                                       *
*              9 : termination by time cut-off                         *
*             10 : geometry boundary crossing                          *
*             11 : termination by energy cut-off                       *
*             12 : termination by escape or leakage                    *
*             13 : nuclear reaction (n,x)                              *
*             14 : nuclear reaction (n,n'x)                            *
*             15 : sequential transport only for tally                 *
*                                                                      *
************************************************************************
      use MMBANKMOD !FURUTA
      use partmod, only: itmxpt ! frtati 2021/10/05
*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param00.inc'
      include 'param.inc'

*-----------------------------------------------------------------------

      common /icomon/ no,mat,ityp,ktyp,jtyp,mtyp,rtyp,ctyp
!$OMP THREADPRIVATE(/icomon/)
      common /wtsave/ oldwt
!$OMP THREADPRIVATE(/wtsave/)
      common /tlgeom/ iblz1,iblz2
!$OMP THREADPRIVATE(/tlgeom/)
      common /tlglat/ ilev1,ilev2,ilat1(5,10),ilat2(5,10)
!$OMP THREADPRIVATE(/tlglat/)

*-----------------------------------------------------------------------

      common /clustt/ nclsts, iclusts(nnn)
!$OMP THREADPRIVATE(/clustt/)
      common /clustw/ jclusts(0:8,nnn),  qclusts(0:12,nnn)
!$OMP THREADPRIVATE(/clustw/)
      common /cntcls/ jcount(3,nnn)
!$OMP THREADPRIVATE(/cntcls/)

*-----------------------------------------------------------------------

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)
      common /tall37/ itcnt(9,itlmax)

      common /tall50/ itlmt(itlmax), ite2l(itlmax)   ! CCSE 2022.08.31
      common /tall51/ eletb(2000), nlete

      common /tall82/ itcnth(9,itlmax)

      common /kmat1d/ idmn(0:kvlmax), idnm(kvmmax)

*-----------------------------------------------------------------------

      dimension   lt(nl)
      dimension   kr(mr)
      dimension   eb(ne+1)
      dimension   tr(np,ne,nr,2)
      dimension   trEVENT(np,ne,nr)         !OBINATA(2012.9.5): as Ct
      real(8),allocatable,save:: tr0(:,:,:) !OBINATA(2012.9.5): as C

      dimension ips(itmxpt) ! frtati 2021/10/05 6 -> itmxpt
      dimension facm(6)

*-----------------------------------------------------------------------

      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)
      common /stat / istdev, irestart, ireschk
      common /cparm/ maxbch,maxcas

*-----------------------------------------------------------------------
      common /dedxfac/ dedxfd
!$OMP THREADPRIVATE(/dedxfac/)

*-----------------------------------------------------------------------

      integer iegsemi, iegsout
      common /egsemi/ iegsemi, iegsout

*-----------------------------------------------------------------------

      real*8 edep
      common/EPCONTedep/ edep
!$OMP THREADPRIVATE(/EPCONTedep/)

      common /cntmx/ ncntmx(3), nctmxsr(3)
!$OMP THREADPRIVATE(/cntmx/)

*-----------------------------------------------------------------------
* check of history counter
*-----------------------------------------------------------------------
      ihistcount = 0 ! history counter index, T.Sato 2022/12/20 for speed up
         if ( ncol.eq.0 .or. ncol.eq.4 ) then
           do i = 1, 3
             if( itcnth(i,m) .eq. 1 ) then
               if( ncntmx(i) .lt. itcnth(i*2+2,m) .or.
     &             ncntmx(i) .gt. itcnth(i*2+3,m) ) then
                 ihistcount = 1
               end if
             end if
           end do
         end if

*-----------------------------------------------------------------------
*        source particle or end of batch ( in case of istdev = 2 )
*
* OBINATA(2012.9.5): change tr(,,,,3) to trEVENT(,,,,)
*-----------------------------------------------------------------------

         if (( ncol .eq. 0 .or. ncol .eq. 4 )
     &                              .and. istdev .eq. 2) then
           if ((nocas.gt.1.or.ncol.eq.0) .and. ihistcount.ne.1 ) then

             tr(:,:,:,1) = tr(:,:,:,1) + trEVENT(:,:,:)
             tr(:,:,:,2) = tr(:,:,:,2) + trEVENT(:,:,:) ** 2

! sumover
           call tletreg_sumover(m,1,
     &                   np,  ne, nr, trEVENT)

           end if

           trEVENT(:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        end of batch ( in case of istdev = 1 )
*
* OBINATA(2012.9.5): modificate for thread parallel
*-----------------------------------------------------------------------

         if ( ncol .eq. 0 .and. istdev .eq. 1) then
!$OMP MASTER
             allocate( tr0(np,ne,nr) )
             tr0(:,:,:) = 0.d0
!$OMP END MASTER
!$OMP BARRIER
!$OMP CRITICAL (tletreg_crit_ist1)
             tr0(:,:,:) = tr0(:,:,:) + trEVENT(:,:,:)
!$OMP END CRITICAL (tletreg_crit_ist1)
!$OMP BARRIER
!$OMP MASTER
             tr(:,:,:,1) = tr(:,:,:,1) + tr0(:,:,:) / maxcas
             tr(:,:,:,2) = tr(:,:,:,2)
     &                     + ( tr0(:,:,:) / maxcas ) ** 2

! sumover
           call tletreg_sumover(m,maxcas,
     &                   np,  ne, nr, tr0)


             deallocate( tr0 )
!$OMP END MASTER

           trEVENT(:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        check of ncol
*-----------------------------------------------------------------------

         if( ncol .lt. 9 ) return

*-----------------------------------------------------------------------
*        check of mat
*-----------------------------------------------------------------------

            if( nl .gt. 0 ) then

                  do i = 1, nl

                     if( itmcn(m) .gt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) goto 502
                     if( itmcn(m) .lt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) return

                  end do

                     if( itmcn(m) .gt. 0 ) return

            end if

  502          continue

*-----------------------------------------------------------------------
*        check region
*-----------------------------------------------------------------------

               jj = 0

            do ii = 1, nr

               call tregck(iblz1,ilev1,ilat1,mr,kr,jj,icc)

               if( icc .ne. 0 ) goto 501

           end do

               return

  501      continue

*-----------------------------------------------------------------------
*        material for LET
*-----------------------------------------------------------------------

               if( itlmt(m) .gt. 0 ) then

                  lmat = idnm( itlmt(m) )

               else if( itlmt(m) .eq. 0 ) then

                  lmat = mat

               else

                  lmat = -idnm( -itlmt(m) )

               end if

*-----------------------------------------------------------------------
*           track length
*-----------------------------------------------------------------------

               tlngth = sqrt( ( xc(ibkxc+no,ipomp+1) -
     &                                          x(ibkx+no,ipomp+1) )**2
     &                      + ( yc(ibkyc+no,ipomp+1) -
     &                                          y(ibky+no,ipomp+1) )**2
     &                      + ( zc(ibkzc+no,ipomp+1) -
     &                                        z(ibkz+no,ipomp+1) )**2 )

*-----------------------------------------------------------------------
*           initial and final energy
*-----------------------------------------------------------------------

                  ein = e(ibke+no,ipomp+1)
                  ecc = ec(ibkec+no,ipomp+1)

                  if( ncol .eq. 9 .or. ncol .eq. 11 ) ecc = 0.d0

*-----------------------------------------------------------------------
cKN Iwase 2014/08/22 for EGS

               if( ( ityp.eq.12 .or. ityp.eq.13 .or. ityp.eq.14 ) .and.
     &               iegsemi .ne. 0 ) then

                     call egs5edxde(ecc,tlngth,ein,mat,ityp)

                     if( ncol .eq. 9 .or. ncol .eq. 11 ) ecc = 0.d0
! for the egs5 electron last hinge ( e=ecut but still have edep (dE) )
                       if( ityp.eq.12 .or. ityp.eq.13) ein = ein + edep

               endif

*-----------------------------------------------------------------------

               do i = 1, nlete

                  if( ein .ge. eletb(i) .and.
     &                ein .lt. eletb(i+1) ) goto 30

               end do

   30             ie1 = min( i, nlete )

               do i = nlete, 1, -1

                  if( ecc .ge. eletb(i) .and.
     &                ecc .lt. eletb(i+1) ) goto 40

               end do

   40             ie2 = max( i, 1 )

*-----------------------------------------------------------------------
*           rrl : track length and rrr : charge particles correction
*-----------------------------------------------------------------------

               rrl = tlngth
               rrr = tlngth
               rrt = 0.0d0

            if( mat .gt. 0 .and. jtyp .ne. 0 ) then

                  call rainge(ein,rng0,mat,ityp,ktyp,jtyp,rtyp)

                  rng1 = max( 0.0d0, rng0 - tlngth )

                  if( rng1 .gt. 1.d+30 ) return

               if( ein .gt. eletb(nlete+1) ) then

                  call rainge(eletb(nlete+1),rngm,mat,
     &                        ityp,ktyp,jtyp,rtyp)

                  rrr = max( 0.0d0, rrr - ( rng0 - rngm ) )
                  rrt = rrt + rng0 -rngm

               end if

            end if

               rrl0 = rrl
               rrr0 = rrr
               rrt0 = rrt

*-----------------------------------------------------------------------
*     check of region
*-----------------------------------------------------------------------

                  jj = 0

*-----------------------------------------------------------------------

      do 100 ii = 1, nr

*-----------------------------------------------------------------------

               call tregck(iblz1,ilev1,ilat1,mr,kr,jj,icc)

               if( icc .eq. 0 ) goto 100

               ir = ii

*-----------------------------------------------------------------------
*        check of particles, only charged particles
*-----------------------------------------------------------------------

               if( jtyp .eq. 0 ) goto 200

            call pcheck(m,np,ityp,ktyp,jtyp,ipn,ips)

               if( ipn .eq. 0 )  goto 200

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( ncnt(ibknct+i,no,ipomp+1) .lt. itcnt(i*2+2,m) .or.
     &                ncnt(ibknct+i,no,ipomp+1) .gt. itcnt(i*2+3,m) )
     &                   goto 200

               end if

            end do

*-----------------------------------------------------------------------
*        check of energy
*-----------------------------------------------------------------------

               if( ein .lt. eletb(1) ) goto 200
               if( ecc .ge. eletb(nlete+1) ) goto 200

*-----------------------------------------------------------------------

               rrl = rrl0
               rrr = rrr0
               rrt = rrt0

*-----------------------------------------------------------------------
*        tally
*-----------------------------------------------------------------------

            do 270 ie = ie1, ie2, -1

                     emie = max( ecc, eletb(ie) )
                     emiu = min( ein, eletb(ie+1) )
                  if( emiu * emie .gt. 0.d0 ) then
                     erg  = sqrt( emiu * emie )
                  else
                     erg  = emiu / 2.d0
                  end if
                     eff  = emiu - emie

                  if( mat .gt. 0 ) then

                     call rainge(emie,rng,mat,ityp,ktyp,jtyp,rtyp)

                     rng = max( 0.0d0, rng - rng1 )
                     rrl = max( 0.0d0, rrr - rng )

                        rrt  = rrt + rrl

                     if( rrt .gt. tlngth ) then

                        rrl = rrl + ( tlngth - rrt )
                        rrt = tlngth

                     else if( ie .eq. ie2 .and.
     &                        ecc .gt. eletb(ie) ) then

                        rrl = rrl + ( tlngth - rrt )

                     end if

                  end if

*-----------------------------------------------------------------------
*              LET bin
*-----------------------------------------------------------------------

               call dedxas(erg,dedx,lmat,ityp,ktyp,jtyp,rtyp)

                  dedx = dedx / 10.d0

               do i = 1, ne

                  if( dedx .ge. eb(i) .and.
     &                dedx .lt. eb(i+1) ) goto 50

               end do

                  goto 260

   50             iel = min( i, ne )

*-----------------------------------------------------------------------

                  if( itunt(m) .eq. 1 .or. itunt(m) .eq. 3 .or.
     &                itunt(m) .eq. 5 .or. itunt(m) .eq. 7 .or.
     &                itunt(m) .eq. 9 .or. itunt(m) .eq. 11 ) then

                        dlet = rrl

                  else

                        dlet = eff

                  end if

*-----------------------------------------------------------------------

                     tlv = oldwt * dlet

*-----------------------------------------------------------------------
                  do ip = 1, ipn

                     trEVENT(ips(ip),iel,ir) =
     &               trEVENT(ips(ip),iel,ir) + tlv

                  end do
*-----------------------------------------------------------------------

  260       continue

                  rrr = rrr - rrl

  270       continue

*-----------------------------------------------------------------------

  200       continue

*-----------------------------------------------------------------------
*     dead particles of produced charged particle
*-----------------------------------------------------------------------

      if( ( ncol .eq. 13 .or. ncol .eq. 14 ) .and.
     &      mat .gt. 0 .and. nclsts .gt. 0 ) then

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( jcount(i,1) .lt. itcnt(i*2+2,m) .or.
     &                jcount(i,1) .gt. itcnt(i*2+3,m) ) goto 300

               end if

            end do

*-----------------------------------------------------------------------
*        dead particle and nucleus except for electron positron
*-----------------------------------------------------------------------

         do j = 1, nclsts

         if( jclusts(4,j) .lt. 0 .and. jclusts(5,j) .ne. 0 .and.
     &       qclusts(7,j) .gt. eletb(1) ) then


                  ipart = jclusts(3,j)
                  kpart = jclusts(7,j)
                  jpart = jclusts(5,j)
                  rpart = qclusts(5,j) * 1000.d0

*-----------------------------------------------------------------------

            call pcheck(m,np,ipart,kpart,jpart,ipn,ips)

               if( ipn .eq. 0 )  goto 285

*-----------------------------------------------------------------------

                  ein = qclusts(7,j)
                  ecc = 0.0d0

               if( ein .lt. eletb(1) ) goto 285

*-----------------------------------------------------------------------

               do i = 1, nlete

                  if( ein .ge. eletb(i) .and.
     &                ein .lt. eletb(i+1) ) goto 35

               end do

   35             ie1 = min( i, nlete )
                  ie2 = 1

*-----------------------------------------------------------------------
*           rrl : track length and rrr : charge particles correction
*-----------------------------------------------------------------------

                  call rainge(ein,rng0,mat,
     &                        ipart,kpart,jpart,rpart)
! T.Sato 2015/2/27, electron and positrons are OK when rng0 > 1.d30
                  if( abs(kpart).ne.11.and.rng0.gt.1.d+30) goto 285

                  tlngth = rng0
                  rng1 = 0.0d0

                  rrl = tlngth
                  rrr = tlngth
                  rrt = 0.0d0

               if( ein .gt. eletb(nlete+1) ) then

                  call rainge(eletb(nlete+1),rngm,mat,
     &                        ipart,kpart,jpart,rpart)

                  rrr = max( 0.0d0, rrr - ( rng0 - rngm ) )
                  rrt = rrt + rng0 -rngm

               end if

*-----------------------------------------------------------------------
*        tally
*-----------------------------------------------------------------------

            do 275 ie = ie1, ie2, -1

                     emie = max( ecc, eletb(ie) )
                     emiu = min( ein, eletb(ie+1) )
                  if( emiu * emie .gt. 0.d0 ) then
                     erg  = sqrt( emiu * emie )
                  else
                     erg  = emiu / 2.d0
                  end if
                     eff  = emiu - emie

                  if( mat .gt. 0 ) then

                     call rainge(emie,rng,mat,
     &                           ipart,kpart,jpart,rpart)

                     rng = max( 0.0d0, rng - rng1 )
                     rrl = max( 0.0d0, rrr - rng )

                        rrt  = rrt + rrl

                     if( rrt .gt. tlngth ) then

                        rrl = rrl + ( tlngth - rrt )
                        rrt = tlngth

                     else if( ie .eq. ie2 .and.
     &                        ecc .gt. eletb(ie) ) then

                        rrl = rrl + ( tlngth - rrt )

                     end if

                  end if

*-----------------------------------------------------------------------
*              LET bin
*-----------------------------------------------------------------------

               call dedxas(erg,dedx,lmat,ipart,kpart,jpart,rpart)

                  dedx = dedx / 10.d0

               do i = 1, ne

                  if( dedx .ge. eb(i) .and.
     &                dedx .lt. eb(i+1) ) goto 55

               end do

                  goto 265

   55             iel = min( i, ne )

*-----------------------------------------------------------------------

                  if( itunt(m) .eq. 1 .or. itunt(m) .eq. 3 .or.
     &                itunt(m) .eq. 5 .or. itunt(m) .eq. 7 .or.
     &                itunt(m) .eq. 9 .or. itunt(m) .eq. 11 ) then

                        dlet = rrl

                  else

                        dlet = eff

                  end if

*-----------------------------------------------------------------------

                     tlv = qclusts(8,j) * dlet

*-----------------------------------------------------------------------
                  do ip = 1, ipn

                     trEVENT(ips(ip),iel,ir) =
     &               trEVENT(ips(ip),iel,ir) + tlv

                  end do
*-----------------------------------------------------------------------

  265       continue

                  rrr = rrr - rrl

  275       continue

*-----------------------------------------------------------------------

  285       continue

         end if
         end do

*-----------------------------------------------------------------------

  300    continue

      end if

*-----------------------------------------------------------------------

  100 continue

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine pletreg(m,np,nr,mr,ne,kr,eb,tr,
     &                   nvl,ivl,rvl,
     &                   nx,ny,nz,xm,ym,zm,igsh,idasa)
*                                                                      *
*       output the LET tally in region mesh                            *
*       last modified by K.Niita on 2005/08/31                         *
*                                                                      *
************************************************************************
      use sangelmod, only: itsans
      use partmod ! frtati 2021/10/05

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param.inc'

*-----------------------------------------------------------------------

      common /taliin/ rsouin, nzztin, nrgnin

*-----------------------------------------------------------------------

      common /verjam/ versn, lastr, iyeav, imonv, idayv

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80
      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall21/ rtfac(itlmax)
      common /tall29/ itrsh(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)

      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)
      common /tall49/ itglt(itlmax)

      common /istcut/ ist_cut, ist_bat

      common /fact01/ facmax(itlmax) ! kitamura23/03/31

*-----------------------------------------------------------------------

      common /volreg/ dvol(kvlmax)

*-----------------------------------------------------------------------

      common /cparm/  maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

      common /talout/ itall

      character fname*100, fnume*3

*-----------------------------------------------------------------------
      character gfnam*100
      common /tall60/ itger(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /mpi00/ npe, me

*-----------------------------------------------------------------------

      dimension   kr(mr)
      dimension   eb(ne+1)
      dimension   ew(ne)
      dimension   vl(nr)
      dimension   lr(nr)
      dimension   tr(np,ne,nr,2)
      dimension   ivl(nvl)
      dimension   rvl(nvl)

      dimension   xm(nx+1)
      dimension   ym(ny+1)
      dimension   zm(nz+1)
      dimension   val(nr)

      integer,allocatable :: ixyz(:)

*-----------------------------------------------------------------------

cfrtati 2021/10/05 6 -> np
      dimension tott(np,2),totnorm(np) ! totnorm is added on 2017/11/21 for normalization

      character hsunit(16)*33

      data hsunit( 1) / 'Track [cm/(keV/um)/source]       '/
      data hsunit( 2) / 'Dose [MeV/(keV/um)/source]       '/
      data hsunit( 3) / 'Track [cm/ln(keV/um)/source]     '/
      data hsunit( 4) / 'Dose [MeV/ln(keV/um)/source]     '/
      data hsunit( 5) / 'Track [cm/source]                '/
      data hsunit( 6) / 'Dose [MeV/source]                '/
      data hsunit( 7) / 'Track [1/cm^2/(keV/um)/source]   '/
      data hsunit( 8) / 'Dose [MeV/cm^3/(keV/um)/source]  '/
      data hsunit( 9) / 'Track [1/cm^2/ln(keV/um)/source] '/
      data hsunit(10) / 'Dose [MeV/cm^3/ln(keV/um)/source]'/
      data hsunit(11) / 'Track [1/cm^2/source]            '/
      data hsunit(12) / 'Dose [MeV/cm^3/source]           '/
      data hsunit(13) / 'L*f(L) [dimensionless]           '/
      data hsunit(14) / 'L*d(L) [keV/um]                  '/

      character cha*1
      data cha /"'"/

cfrtati 2021/10/05 chl, chm moved to partmod

cfrtati 2021/10/05 6 -> itmxpt
      character chp(itmxpt)*11  ! kitamura22/03/31
      character chq(itmxpt)*9   ! kitamura22/03/31


      character rpa*1
      data rpa /'}'/
      character yen*1

      include 'samepage_include/samepage000_norm.inc'

      include 'samepage_include/samepage001.inc'

      yen  = char(92)
      allocate( ixyz(max((nx+1)*(ny+1),(ny+1)*(nz+1),(nx+1)*(nz+1))) )

*-----------------------------------------------------------------------
      np_mxang = np
      if ( itmxang(m).ne.0 .and. iabs(itmxang(m)).lt.np ) then
        np_mxang = iabs(itmxang(m))
      end if

*-----------------------------------------------------------------------
*     for igshow
*-----------------------------------------------------------------------

         if( igsh .eq. 0 ) then

            npg = np
            neg = ne

         else

            npg = 1
            neg = 1

         end if

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

               call wtpname(m,np,chp,chq)

*-----------------------------------------------------------------------
*           itunt(m) = 1 : cm/(keV/um)/source
*                    = 2 : MeV/(keV/um)/source
*                    = 3 : cm/ln(keV/um)/source
*                    = 4 : MeV/ln(keV/um)/source
*                    = 5 : cm/source
*                    = 6 : MeV/source
*                    = 7 : 1/cm^2/(keV/um)/source
*                    = 8 : MeV/cm^3/(keV/um)/source
*                    = 9 : 1/cm^2/ln(keV/um)/source
*                    =10 : MeV/cm^3/ln(keV/um)/source
*                    =11 : 1/cm^2/source
*                    =12 : MeV/cm^3/source
*                    =13 : L*f(L)
*                    =14 : L*d(L)
*-----------------------------------------------------------------------

            if( itunt(m) .eq. 1 .or. itunt(m) .eq. 2 .or.
     &          itunt(m) .eq. 7 .or. itunt(m) .eq. 8 .or.
     &          itunt(m) .eq. 13) then  ! T.Sato 2017/11/21

               do i = 1, ne

                  ew(i) = eb(i+1) - eb(i)

               end do
               ew_sum = eb(ne+1) - eb(1)

            else
     &      if( itunt(m) .eq. 3 .or. itunt(m) .eq. 4 .or.
     &          itunt(m) .eq. 9 .or. itunt(m) .eq. 10 .or.
     &          itunt(m) .eq. 14 ) then ! T.Sato 2017/11/21

               do i = 1, ne

                  ew(i) = log( eb(i+1) / eb(i) )

               end do
               ew_sum = log( eb(ne+1) / eb(1) )

            else

               do i = 1, ne

                  ew(i) = 1.d0

               end do
               ew_sum = 1.0d0

            end if

*-----------------------------------------------------------------------
*        set mesh volume and name
*-----------------------------------------------------------------------

               call tregvl(nr,mr,kr,vl,lr,nvl,ivl,rvl)

*-----------------------------------------------------------------------
*        ( unit = 1-6 ; vol = 1.0 )
*-----------------------------------------------------------------------

            vl_sum = sum(vl(:))

            if( itunt(m) .le. 6 .or. itunt(m) .ge. 13) then  ! T.Sato 2017/11/21

               do ir = 1, nr

                  vl(ir) = 1.0d0

               end do
               vl_sum = 1.0d0

            end if

*-----------------------------------------------------------------------
*        relative error and  unit conversion
*        c1 : normalization for source
*-----------------------------------------------------------------------

         if( igsh .eq. 0 ) then

                  cmax = 0.0
                  cmin = 1.e+33
                  dnon = 1.e-33
                  isdz = 0
                  stdm = 0.0
                  itstd(m) = 1

               if ( rsouin .gt. 0d0 ) then ! S.H. (2016.7.26)

                  c1 = 1.0d+0 / rsouin

               else

                  c1 = 0d0

               end if

            facmax(m) = 1.d0
            if( rtfac(m) .lt. 0.d0 ) then
               facmax(m) = 0.d0

               do 101 ir = 1, nr
               do 101 ie = 1, ne
               do 101 ip = 1, np

                  if( tr(ip,ie,ir,1) .gt. 0.d0 ) then

                     fmaxfc = tr(ip,ie,ir,1) / vl(ir) / ew(ie)

                     if( facmax(m) .lt. fmaxfc) facmax(m) = fmaxfc

                  end if

  101          continue

            end if

            do 100 ir = 1, nr
            do 100 ie = 1, ne
            do 100 ip = 1, np

               if( tr(ip,ie,ir,1) .gt. 0.d0 ) then

                  call calc_stdev(m,Xa,sigx,
     &                            tr(ip,ie,ir,1),
     &                            tr(ip,ie,ir,2),
     &             abs(rtfac(m)/facmax(m))/vl(ir)/ew(ie))

                  tr(ip,ie,ir,1) = Xa
                  tr(ip,ie,ir,2) = sigx

                  if( sigx .gt. stdm ) stdm = sigx
                  if( tr(ip,ie,ir,1) .gt. cmax )
     &                     cmax = tr(ip,ie,ir,1)

                  if( tr(ip,ie,ir,1) .lt. cmin )
     &                     cmin = tr(ip,ie,ir,1)

               else

                  isdz = 1
                  tr(ip,ie,ir,2) = 0.0

               end if
! sumover
               fact_in = abs(rtfac(m)/facmax(m))
               call pletreg_sumover_stdev(0,m,ip,ie,ir,
     &                fact_in,ew(ie),vl(ir),ew_sum,vl_sum)


  100       continue

            if( nobch .gt. ist_bat ) then
            if( rtstd(m) .gt. 0.d0 .and.
     &          stdm .gt. 0.d0 .and. isdz .eq. 0 .and.
     &          stdm .lt. rtstd(m) ) itstd(m) = 0
            end if

         end if

*-----------------------------------------------------------------------
*     out put unit = 31  : temporary number
*-----------------------------------------------------------------------

      do 900 iax = 1, itfln(m)

         if( igsh .ne. 0 .and.
     &     ( itaxs(m,iax) .lt. 7 .or. itrsh(m) .eq. 0 ) ) goto 900

         if( (itall .eq. 2 .and. nobch .lt. maxbch .and. igsh .eq. 0)
     &        .or. ( itall .eq. 4 .and. igsh .eq. 0 ) ) then

            call mk_2dnumfn(ctfln(m,iax),fname,itfll(m,iax),
     &           nobch,maxbch,npe)

         else

            fname = ctfln(m,iax)

         end if

            iot = 31
            open(iot, file = fname, status = 'unknown' )

