               if( itayl(m) .eq. 0 ) then

                  write(iot,'( "y: x [cm]")')

               else

                  write(iot,'( "y: ",200a1)')
     &                       (itayt(m)(i:i),i=1,itayl(m))

               end if

*-----------------------------------------------------------------------

         if( igsh .eq. 0 ) then

               do i = 1, nr

                  val(i) = tr(ip,ie,i,it,1)

               end do

                  izlog = 1
                  if( itanl(m) .gt. 0 )
     &            call anset(itang(m),itanl(m),
     &                       form,xfac,afac,cmin,cmax,izlog,inocm,inolg)

            if( izlog .eq. 0 ) then

               do i = 1, nr

                  if( val(i) .gt. dnon .and. cmin .ne. cmax ) then

                     val(i) = ( val(i) - cmin ) / ( cmax - cmin )
                     val(i) = max(0.0d0,val(i))
                     val(i) = min(1.0d0,val(i))

                  else

                     val(i) = -1.0

                  end if

               end do

            else

               do i = 1, nr

                  if( val(i) .gt. dnon .and. cmin .ne. cmax ) then

                     val(i) = log10(val(i)/cmin) / log10(cmax/cmin)
                     val(i) = max(0.0d0,val(i))
                     val(i) = min(1.0d0,val(i))

                  else

                     val(i) = -1.0d0

                  end if

               end do

            end if

         end if

*-----------------------------------------------------------------------

               if( inum .eq. 1 ) then

                  form  = ( xm(nx+1) - xm(1) )
     &                  / ( zm(nz+1) - zm(1) )
                  xfac  = 0.9
                  afac  = 0.8
