     &                     "  emax  &=&",1pe13.4," [MeV]"/
     &                     "  y     &=&",1pe13.4," [cm]"/
     &                     "  part. &=& ",a8)')
     &                     yen, eb(ie), eb(ie+1),
     &                     yval, chq(ip)
                  end if
                  if( ittty(m) .ne. 0 ) then
                     write(iot,'(
