*-----------------------------------------------------------------------

         if( itaxs(m,iax) .eq. 1 ) then

               inum = 0

            do iri = 1, nr, nrstepi
            do iti = 1, nt, ntstepi
            do ipi = 1, np, npstepi
               ir = iri
               it = iti
               ip = ipi

               inum = inum + 1

               ireg = lr(ir)

                  write(iot,'(/"#",78("-"))')

               if( inum .eq. 1 ) then
                  write(iot,'( "#newpage:")')
               else
                  write(iot,'( " newpage:")')
               end if

               if( rtfac(m) .lt. 0.d0 )
     &           write(iot,
