               if( ittty(m) .ne. 0 ) then
                  write(iot,'(
     &            "#  it =",i3,/
     &            "#   t = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                     it, tb(it), tb(it+ntstepi)
               end if

               if( itaxl(m) .eq. 0 ) then

                  write(iot,'(/"x: Deposit Energy [MeV]")')

               else

                  write(iot,'(/"x: ",200a1)')
     &                       (itaxt(m)(i:i),i=1,itaxl(m))

               end if

               if( itayl(m) .eq. 0 ) then

                  write(iot,'( "y: ",a22)') hsunit(itunt(m))

               else

                  write(iot,'( "y: ",200a1)')
     &                       (itayt(m)(i:i),i=1,itayl(m))

               end if

               if( itety(m) .eq. 3 .or. itety(m) .eq. 5 ) then

                  write(iot,'( "p: xlog ylog afac(0.8) form(0.9)")')

               else

                  write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

               end if

               if( itanl(m) .gt. 0 ) then

                  write(iot,'( "p: ",200a1)')
     &            ( itang(m)(i:i),i = 1, itanl(m) )

               end if

               if( itsans(m) .gt. 0 ) then

                  call write_sangel(iot,m,0)

               end if

       include 'samepage_include/pert_erg_nei.inc'

*-----------------------------------------------------------------------

             if(iloopmode .eq. 0) then
                  if( ittty(m) .eq. 0 ) then
                     write(iot,'(/a1,"no. =",i3,
     &                        ",  reg  =",i7,a1)')
     &                        cha, inum, ireg, cha
                  else
                     write(iot,'(/a1,"no. =",i3,
     &                        ",  reg  =",i7,",  it =",i3,a1)')
     &                        cha, inum, ireg, it, cha
                  end if

             else
                write(changelsub(1),'(a1,"no. =",i3)') cha,inum
                write(changelsub(2),'(",  part = ",a)') chp(ipi)(3:10)
                write(changelsub(3),'(",  reg  =",i7)') ireg
                write(changelsub(4),'(",  ie =",i3)') ie
                write(changelsub(5),'(",  it =",i3)') it
                write(changelsub(6),'(a1)') cha
               if( ittty(m) .eq. 0 ) then
                 changelsub(5) = " "
                end if
               changelsub(4) = " "
               if(iloopmode .eq. 2) then
                  changelsub(3) = " "
               end if
               if(iloopmode .eq. 1) then
                  changelsub(4) = " "
               end if
               if(iloopmode .eq. 10) then
                  changelsub(5) = " "
               end if
                angeltitle = trim(changelsub(1))//trim(changelsub(2))//
     &                       trim(changelsub(3))//trim(changelsub(4))//
     &                       trim(changelsub(5))//trim(changelsub(6))
                write(iot,'(/a)') trim(angeltitle)
          end if

               write(iot,'("msuc: {",a1,"huge ",80a1)')
     &                  yen, ( ittle(m)(i:i), i = 1, ittll(m) ), rpa

               write(iot,'("msdr: {",a1,"it plotted by ",
     &                  a1,"ANGEL ",a1,"version}")') yen, yen, yen
               write(iot,'("msdl: {",a1,"it calculated by ",
     &                  a1,"PHITS ",f5.2"}")') yen, yen, versn


                     write(iot,'("wt: s(0.7)",/
     &                     a1,"vspace{-3}"/
     &                     "   vol  &=&",1pe13.4," [cm^3]")')
     &                     yen, vl(ir)
               if(iloopmode .ge. 1) then
                     write(iot,'("  part  &=& ",a)') chp(ipi)(3:10)
               endif
               if( ittty(m) .ne. 0 ) then
                  write(iot,'(
     &                     "  tmin  &=&",1pe13.4," [nsec]"/
     &                     "  tmax  &=&",1pe13.4," [nsec]")')
     &                     tb(it), tb(it+ntstepi)
               end if
                     write(iot,'("e:")')

            end do

            end do
            end do

*-----------------------------------------------------------------------
*        tet axis
*-----------------------------------------------------------------------

         else if( itaxs(m,iax) .eq. 14 ) then

               inum = 0

            if(nestepi .gt . ne - nei +1) then
               nestepi = ne - nei +1
               nsame = max(nrstepi, ntstepi, nestepi, npstepi)
               np_mxang =min(np_mxang, nsame)
            end if
            do iei = nei, ne, nestepi
            do iti = 1, nt, ntstepi
            do ipi = 1, np, npstepi
               ie = iei
               it = iti
               ip = ipi

               inum = inum + 1

                  write(iot,'(/"#",78("-"))')

               if( inum .eq. 1 ) then
                  write(iot,'( "#newpage:")')
               else
                  write(iot,'( " newpage:")')
               end if

               if( rtfac(m) .lt. 0.d0 )
     &           write(iot,
     &           '( "#restart maximum for normalization:",1p1e14.7)')
     &           facmax(m)

               if(iloopmode .ge. 1) then
                  write(iot,'("#   ",a)') chp(ipi)(3:10)
               endif

                  write(iot,'("#   no. =",i3)') inum
               if( nei .eq. 1 ) then
                  write(iot,'(
     &            "#  ie =",i3,/
     &            "#   e = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                        ie, eb(ie), eb(ie+nestepi)
               end if
               if( ittty(m) .ne. 0 ) then
                  write(iot,'(
     &            "#  it =",i3,/
     &            "#   t = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                     it, tb(it), tb(it+ntstepi)
               end if

               if( itaxl(m) .eq. 0 ) then

                  write(iot,'(/"x: Serial Num. of tetrahedron")')

               else

                  write(iot,'(/"x: ",200a1)')
     &                       (itaxt(m)(i:i),i=1,itaxl(m))

               end if

               if( itayl(m) .eq. 0 ) then

                  write(iot,'( "y: ",a22)') hsunit(itunt(m))

               else

                  write(iot,'( "y: ",200a1)')
     &                       (itayt(m)(i:i),i=1,itayl(m))

               end if

               write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

               if( itanl(m) .gt. 0 ) then

                  write(iot,'( "p: ",200a1)')
     &            ( itang(m)(i:i),i = 1, itanl(m) )

               end if

               if( itsans(m) .gt. 0 ) then

                  call write_sangel(iot,m,0)

               end if

       include 'samepage_include/pert_reg.inc'

*-----------------------------------------------------------------------

             if(iloopmode .eq. 0) then
              if( nei .eq. 0 ) then
                  if( ittty(m) .eq. 0 ) then
                     write(iot,'(/a1,"no. =",i3,a1)')
     &                     cha, inum, cha
                  else
                     write(iot,'(/a1,"no. =",i3,
     &                     ",  it =",i3,a1)')
     &                     cha, inum, it, cha
                  end if
              else
                  if( ittty(m) .eq. 0 ) then
                     write(iot,'(/a1,"no. =",i3,",  ie =",
     &                     i3,a1)')
     &                     cha, inum, ie, cha
                  else
                     write(iot,'(/a1,"no. =",i3,",  ie =",
     &                     i3,",  it =",i3,a1)')
     &                     cha, inum, ie, it, cha
                  end if
              end if
             else
                write(changelsub(1),'(a1,"no. =",i3)') cha,inum
                write(changelsub(2),'(",  part = ",a)') chp(ipi)(3:10)
                write(changelsub(3),'(",  reg  =",i7)') ireg
                write(changelsub(4),'(",  ie =",i3)') ie
                write(changelsub(5),'(",  it =",i3)') it
                write(changelsub(6),'(a1)') cha
               if( ittty(m) .eq. 0 ) then
                 changelsub(5) = " "
                end if
               changelsub(3) = " "
               if(iloopmode .eq. 2) then
