     &            "#   r = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &            "#   z = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                        inum, ir, iz,
     &                        rm(ir), rm(ir+nrstepi),
     &                        zm(iz), zm(iz+nzstepi)
               if( ittty(m) .ne. 0 ) then
                  write(iot,'(
     &            "#  it =",i3,/
