             else
               write(changelsub(1),'(a1,"no. =",i3)') cha,inum
               write(changelsub(2),'(",  part = ",a)') chp(ipi)(3:10)
               write(changelsub(3),'(",  ir =",i3)') ir
               write(changelsub(4),'(",  iz =",i3)') iz
               write(changelsub(5),'(",  ie =",i3)') ie
               write(changelsub(6),'(",  it =",i3)') it
               write(changelsub(7),'(a1)') cha
               if( ne .eq. 0 ) then
                 changelsub(5) = " "
               end if
               if( ittty(m) .eq. 0 ) then
                 changelsub(6) = " "
               end if

                 changelsub(5) = " "

               if(iloopmode .eq. 5) then
