               end if
               if(iloopmode .eq. 6) then
                 changelsub(3) = " "
               end if
               if(iloopmode .eq. 1) then
                  changelsub(5) = " "
               end if
               if(iloopmode .eq. 10) then
                  changelsub(6) = " "
               end if
                angeltitle = trim(changelsub(1))//trim(changelsub(2))//
