*-----------------------------------------------------------------------

         else if( itaxs(m,iax) .eq. 6 ) then

               inum = 0

            if(nestepi .gt . ne - nei +1) then
               nestepi = ne - nei +1
              nsame = max(nzstepi, nrstepi, ntstepi, nestepi, npstepi)
              np_mxang =min(np_mxang, nsame)
            end if

            do iei = nei, ne, nestepi
