               else
                  write(iot,'("#   no. =",i3,3x,
     &            "ie  =",i3,3x,
     &            "iz  =",i3,/
     &            "#   e = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &            "#   z = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                        inum, ie, iz,
     &                        eb(ie), eb(ie+nestepi),
