     &                       ")")') zmin, zmax

               write(iot,'( "p: ymin(",1p1g14.7,") ymax(",1p1g14.7,
     &                       ")")') xmin, xmax

      end if

*-----------------------------------------------------------------------

            end do
            end do
            end do
            end do

*-----------------------------------------------------------------------

            if ( itbmp(m) .ne. 0 ) then

               numIndex = 4
               allocate( bmpfIType(1:numIndex) )
               allocate( bmpfIndex(1:numIndex) )
               bmpfIType = (/ 't', 'e', 'p', 'y' /)
               bmpfIndex = (/ ntg, (neg-nei+1), npg, ny /)
               bmpWidth  = nz
               bmpHeight = nx

            end if

            if ( itvtk(m) .ne. 0 ) then

               call open_file(isunit_vtk_meta_default,
     &                 "", isunit_vtk_meta, ios, .true.)
               call open_file(isunit_vtk_default,
     &                 "", isunit_vtk, ios, .true.)

               iaxs = 3
               nparam = 2

               write(isunit_vtk_meta) ntg

               do it = 1, ntg

                  write(isunit_vtk_meta) iaxs
                  write(isunit_vtk_meta) nparam
                  write(isunit_vtk_meta) 'p', 'e'
                  write(isunit_vtk_meta) npg, (neg-nei+1)

                  write(isunit_vtk_meta) nx,ny,nz
                  write(isunit_vtk_meta)
     &                    ( xm(ix), ix=1,nx+1 )
                  write(isunit_vtk_meta)
     &                    ( ym(iy), iy=1,ny+1 )
                  write(isunit_vtk_meta)
     &                    ( zm(iz), iz=1,nz+1 )

                  do ip = 1, npg
                  do ie = nei, neg

                     write(isunit_vtk_meta) ip, (ie-nei+1)

                     write(isunit_vtk)
     &                       ( ( ( tr(ip,ie,it,icf(ix,iy,iz),ioe),
     &                             ix=1,nx ),
     &                             iy=1,ny ),
     &                             iz=1,nz )

                  end do
                  end do

               end do

               iuni = itgsh(m) * 2 - 1 + igsh
               ires = itres(m)

               call open_file(isunit_vtk_rm_default,
     &                 "", isunit_vtk_rm, ios, .true.)

               if ( itgsh(m) .ne. 0 .and. ioe .eq. 1 ) then

                  call open_file(isunit_vtk_geom_default,
     &                    "", isunit_vtk_geom, ios, .true.)
                  call open_file(isunit_vtk_geom_meta_default,
     &                    "", isunit_vtk_geom_meta, ios, .true.)

               else
                  isunit_vtk_geom = 0
                  isunit_vtk_geom_meta = 0
               end if

               call vtk_set_cell_regmat(
     &                 isunit_vtk_rm,
     &                 isunit_vtk_geom, isunit_vtk_geom_meta,
     &                 nx, ny, nz, xm, ym, zm,
     &                 iaxs,iuni,ires, igser,
     &                 1,1,krr,vll,itmtr(m,4))

            end if

*-----------------------------------------------------------------------

         end if       ! itaxs

            call prestart(m,iot) !OBINATA(2012.8.3)

            close(iot)

*-----------------------------------------------------------------------

         if( iteps(m) .ne. 0 ) then

            open(iot, file = fname, status = 'unknown' )
            call a_angel(idasa,fname)

         end if

         if ( itbmp(m) .ne. 0 ) then

            open(iot, file = fname, status = 'unknown' )
            call bitmap_a_angel(
     &              idasa, fname,
     &              bmpWidth, bmpHeight,
     &              bmpfIType, bmpfIndex, numIndex)
            close(iot)

         end if

         if ( itvtk(m) .ne. 0 ) then

            rewind(isunit_vtk_meta)
            rewind(isunit_vtk)

            call vtk_write_tally(
     &              itvtkfmt(m),
     &              isunit_vtk_meta, isunit_vtk,
     &              isunit_vtk_rm,
     &              fname)

            call close_file(isunit_vtk_meta)
            call close_file(isunit_vtk)

            if ( itgsh(m) .ne. 0 .and. ioe .eq. 1 .and.
     &           isunit_vtk_geom.gt.0 .and.
     &           isunit_vtk_geom_meta.gt.0 ) then

               rewind(isunit_vtk_geom)
               rewind(isunit_vtk_geom_meta)

               isText = (itvtkfmt(m).eq.0)

               call vtk_create_filename(
     &                 fname, outFilename, .true., 0, 0)
               call open_file(iunit_vtk_g_default,
     &                 outFilename, iunit_vtk_g, ios, isText)
               call vtk_write_polydata(
     &                 itvtkfmt(m), iunit_vtk_g,
     &                 isunit_vtk_geom, isunit_vtk_geom_meta)
               call close_file(iunit_vtk_g)

            end if

         end if

         if ( allocated(bmpfIType) ) deallocate( bmpfIType )
         if ( allocated(bmpfIndex) ) deallocate( bmpfIndex )

         call close_file(isunit_vtk_rm)
         call close_file(isunit_vtk_geom)
         call close_file(isunit_vtk_geom_meta)

*-----------------------------------------------------------------------

  900    continue

*-----------------------------------------------------------------------
         deallocate( ixyz )
         deallocate( vl ) !FURUTA20190208
      include 'samepage_include/samepage999.inc'

      return
      end


************************************************************************
* unused                                                                     *
      subroutine tdpst2reg(ncol,m,np,nr,mr,ne1,ne2,nt,kr,eb1,eb2,
     &                     tb,tr,tr0)
*                                                                      *
*       Deposit2 tally in region mesh                                  *
*       last modified by K.Niita on 2005/11/14                         *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*      ncol  ..... reaction type                                       *
*              0 : end of batch                                        *
*              4 : source particle                                     *
*                                                                      *
*              9 : termination by time cut-off                         *
*             10 : geometry boundary crossing                          *
*             11 : termination by energy cut-off                       *
*             12 : termination by escape or leakage                    *
*             13 : nuclear reaction (n,x)                              *
*             14 : nuclear reaction (n,n'x)                            *
*             15 : sequential transport only for tally                 *
*                                                                      *
************************************************************************
      use MMBANKMOD !FURUTA
      use partmod, only: itmxpt ! frtati 2021/10/05
*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param00.inc'
      include 'param.inc'

*-----------------------------------------------------------------------

      common /icomon/ no,mat,ityp,ktyp,jtyp,mtyp,rtyp,ctyp
!$OMP THREADPRIVATE(/icomon/)
      common /wtsave/ oldwt
!$OMP THREADPRIVATE(/wtsave/)
      common /tlgeom/ iblz1,iblz2
!$OMP THREADPRIVATE(/tlgeom/)
      common /tlglat/ ilev1,ilev2,ilat1(5,10),ilat2(5,10)
!$OMP THREADPRIVATE(/tlglat/)

*-----------------------------------------------------------------------

      common /clustt/ nclsts, iclusts(nnn)
!$OMP THREADPRIVATE(/clustt/)
      common /clustw/ jclusts(0:8,nnn),  qclusts(0:12,nnn)
!$OMP THREADPRIVATE(/clustw/)
      common /cntcls/ jcount(3,nnn)
!$OMP THREADPRIVATE(/cntcls/)

*-----------------------------------------------------------------------

      common /tall37/ itcnt(9,itlmax)

      common /tall50/ itlmt(itlmax), ite2l(itlmax)   ! CCSE 2022.08.31
      common /tall55/ itlmt2(itlmax)

      common /tall53/ itdfn(itlmax,2)
      common /tall54/ itdfn2(itlmax,2)

      common /tall51/ eletb(2000), nlete

      common /kmat1d/ idmn(0:kvlmax), idnm(kvmmax)

*-----------------------------------------------------------------------

      dimension   kr(mr)
      dimension   eb1(ne1+1)
      dimension   eb2(ne2+1)
      dimension   tb(nt+1)
      dimension   tr(np,0:ne1,0:ne2,nt,2)

      dimension ips(itmxpt) ! frtati 2021/10/05 6 -> itmxpt

*-----------------------------------------------------------------------

      save sweight
!$OMP THREADPRIVATE(sweight)
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

*-----------------------------------------------------------------------
      common /dedxfac/ dedxfd
!$OMP THREADPRIVATE(/dedxfac/)

*-----------------------------------------------------------------------

      real*8 edep
      common/EPCONTedep/ edep
!$OMP THREADPRIVATE(/EPCONTedep/)

      integer iegsemi, iegsout
      common /egsemi/ iegsemi, iegsout
C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

! sumover

      real(8) tr0(np,0:ne1,0:ne2,nt)

      tr0(:,:,:,:) = 0.0d0

*-----------------------------------------------------------------------
*     deposit : ncol = 0, 4 and ns = 4
*-----------------------------------------------------------------------

      if( ncol .eq. 0 .or. ncol .eq. 4 ) then

         if( nocas .gt. 1 .or. ncol .eq. 0 ) then

            do ip = 1, np
            do it = 1, nt

                  heat1 = tr(ip,1,0,it,1)
                  heat2 = tr(ip,0,1,it,1)

               if( ( heat1 .gt.  0.0d0 .or. heat2 .gt. 0.0d0 ) .and.
     &             heat1 .ge. eb1(1) .and. heat1 .lt. eb1(ne1+1) .and.
     &             heat2 .ge. eb2(1) .and. heat2 .lt. eb2(ne2+1) ) then

                  do ie1 = 1, ne1
                  do ie2 = 1, ne2

                     if( heat1 .ge. eb1(ie1) .and.
     &                   heat1 .lt. eb1(ie1+1) .and.
     &                   heat2 .ge. eb2(ie2) .and.
     &                   heat2 .lt. eb2(ie2+1) ) then

! sumover
                        tr0(ip,ie1,ie2,it) = tr0(ip,ie1,ie2,it)
     &                                      + sweight

        if (italsh .eq. 0 ) then
                        tr(ip,ie1,ie2,it,1) = tr(ip,ie1,ie2,it,1)
     &                                      + sweight
                        tr(ip,ie1,ie2,it,2) = tr(ip,ie1,ie2,it,2)
     &                                      + sweight**2
        else
!$OMP CRITICAL (tr_tdpst2reg)
                        tr(ip,ie1,ie2,it,1) = tr(ip,ie1,ie2,it,1)
     &                                      + sweight
                        tr(ip,ie1,ie2,it,2) = tr(ip,ie1,ie2,it,2)
     &                                      + sweight**2
!$OMP END CRITICAL (tr_tdpst2reg)
        endif

                     end if

                  end do
                  end do
               end if

            end do
            end do

! sumover

         end if

*-----------------------------------------------------------------------
*        save initial weight and zero set
*-----------------------------------------------------------------------

         if( ncol .eq. 4 ) then

            sweight = oldwt

            do ip = 1, np
            do it = 1, nt
! sumover
               tr0(ip,1,0,it) = 0.0d0
               tr0(ip,0,1,it) = 0.0d0

            do ik = 1, 2

               tr(ip,1,0,it,ik) = 0.0d0
               tr(ip,0,1,it,ik) = 0.0d0

            end do
            end do
            end do

         end if

      end if

*-----------------------------------------------------------------------
*        check of ncol
*-----------------------------------------------------------------------

         if( ncol .lt. 9 ) return

*-----------------------------------------------------------------------
*        check region
*-----------------------------------------------------------------------

               jj = 0

      do 1000 ii = 1, nr

               call tregck(iblz1,ilev1,ilat1,mr,kr,jj,icc)

               if( icc .eq. 0 ) goto 1000

               ir = ii

*-----------------------------------------------------------------------
*        ir = 1, 2 only
*-----------------------------------------------------------------------

               if( ir .eq. 1 ) then

                  itlmat = itlmt(m)
                  itdfun = itdfn(m,1)

                  i1 = 1
                  i2 = 0

               else

                  itlmat = itlmt2(m)
                  itdfun = itdfn2(m,1)

                  i1 = 0
                  i2 = 1

               end if

*-----------------------------------------------------------------------
*        check time
*-----------------------------------------------------------------------

               tin = abs(t(ibkt+no,ipomp+1))

               if( tin .lt. tb(1) ) return
               if( tin .ge. tb(nt+1) ) return

            do i = 1, nt

               if( tin .ge. tb(i) .and.
     &             tin .lt. tb(i+1) ) goto 50

            end do

   50          it = i

*-----------------------------------------------------------------------
*        material for LET
*-----------------------------------------------------------------------

               if( itlmat .gt. 0 ) then

                  lmat = idnm( itlmat )

               else if( itlmat .eq. 0 ) then

                  lmat = mat

               else

                  lmat = -idnm( -itlmt(m) )

               end if

*-----------------------------------------------------------------------
*           track length
*-----------------------------------------------------------------------

               tlngth = sqrt( ( xc(ibkxc+no,ipomp+1) -
     &                                        x(ibkx+no,ipomp+1) )**2
     &                      + ( yc(ibkyc+no,ipomp+1) -
     &                                        y(ibky+no,ipomp+1) )**2
     &                      + ( zc(ibkzc+no,ipomp+1) -
     &                                        z(ibkz+no,ipomp+1) )**2 )

*-----------------------------------------------------------------------
*           initial and final energy
*-----------------------------------------------------------------------

                  ein = e(ibke+no,ipomp+1)
                  ecc = ec(ibkec+no,ipomp+1)

                  if( ncol .eq. 9 .or. ncol .eq. 11 ) ecc = 0.d0

*-----------------------------------------------------------------------
cKN Iwase 2014/08/22 for EGS

               if( ( ityp.eq.12 .or. ityp.eq.13 .or. ityp.eq.14 ) .and.
     &               iegsemi .ne. 0 ) then

                     call egs5edxde(ecc,tlngth,ein,mat,ityp)

                  if(ncol.eq.9 .or. ncol.eq.11) then
                     ecc = 0d0
                     if( ityp.eq.12 .or. ityp.eq.13 ) ein = ein + edep
                  endif

               endif

*-----------------------------------------------------------------------
*        dedxfnc is specified
*-----------------------------------------------------------------------

         if( itdfun .ne. 0 ) then

               do i = 1, nlete

                  if( ein .ge. eletb(i) .and.
     &                ein .lt. eletb(i+1) ) goto 30

               end do

   30             ie1 = min( i, nlete )

               do i = nlete, 1, -1

                  if( ecc .ge. eletb(i) .and.
     &                ecc .lt. eletb(i+1) ) goto 40

               end do

   40             ie2 = max( i, 1 )

*-----------------------------------------------------------------------
*           rrl : track length and rrr : charge particles correction
*-----------------------------------------------------------------------

               rrl = tlngth
               rrr = tlngth
               rrt = 0.0d0

            if( mat .gt. 0 .and. jtyp .ne. 0 ) then

                  call rainge(ein,rng0,mat,ityp,ktyp,jtyp,rtyp)

                  rng1 = max( 0.0d0, rng0 - tlngth )

                  if( rng1 .gt. 1.d+30 ) return

               if( ein .gt. eletb(nlete+1) ) then

                  call rainge(eletb(nlete+1),rngm,mat,
     &                        ityp,ktyp,jtyp,rtyp)

                  rrr = max( 0.0d0, rrr - ( rng0 - rngm ) )
                  rrt = rrt + rng0 -rngm

               end if

            end if

               rrl0 = rrl
               rrr0 = rrr
               rrt0 = rrt

         end if

*-----------------------------------------------------------------------
*        check of particles, only charged particles
*-----------------------------------------------------------------------
cKN Iwase, T.Sato 2016/1/29 delete EGS exception

            if( jtyp .eq. 0 .and. ityp .ne. 14 ) goto 200

            call pcheck(m,np,ityp,ktyp,jtyp,ipn,ips)

               if( ipn .eq. 0 )  goto 200

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( ncnt(ibknct+i,no,ipomp+1) .lt. itcnt(i*2+2,m) .or.
     &                ncnt(ibknct+i,no,ipomp+1) .gt. itcnt(i*2+3,m) )
     &                        goto 200

               end if

            end do

*-----------------------------------------------------------------------
*        dedxfnc is specified
*-----------------------------------------------------------------------

         if( itdfun .ne. 0 ) then

               if( ein .lt. eletb(1) ) goto 200
               if( ecc .ge. eletb(nlete+1) ) goto 200

*-----------------------------------------------------------------------

               rrl = rrl0
               rrr = rrr0
               rrt = rrt0

*-----------------------------------------------------------------------
*           tally
*-----------------------------------------------------------------------

            do 270 ie = ie1, ie2, -1

                     emie = max( ecc, eletb(ie) )
                     emiu = min( ein, eletb(ie+1) )

                  if( emiu * emie .gt. 0.d0 ) then
                     erg  = sqrt( emiu * emie )
                  else
                     erg  = emiu / 2.d0
                  end if

                  if( mat .gt. 0 ) then

                     call rainge(emie,rng,mat,ityp,ktyp,jtyp,rtyp)

                     rng = max( 0.0d0, rng - rng1 )
                     rrl = max( 0.0d0, rrr - rng )

                        rrt  = rrt + rrl

                     if( rrt .gt. tlngth ) then

                        rrl = rrl + ( tlngth - rrt )
                        rrt = tlngth

                     else if( ie .eq. ie2 .and.
     &                        ecc .gt. eletb(ie) ) then

                        rrl = rrl + ( tlngth - rrt )

                     end if

                  end if

*-----------------------------------------------------------------------
*              dedx value multiplyed user factor
*-----------------------------------------------------------------------

               call dedxas(erg,dedx,lmat,ityp,ktyp,jtyp,rtyp)

                  dedx = dedx / 10.d0
                  dtrk = rrl
                  eini = emiu
                  efin = emie

               if( itdfun .eq. 1 ) then

                  call usrdfn1(ityp,ktyp,jtyp,rtyp,
     &                         dedx,dtrk,eini,efin,dhet)

               else if( itdfun .eq. 2 ) then

                  call usrdfn2(ityp,ktyp,jtyp,rtyp,
     &                         dedx,dtrk,eini,efin,dhet)

               end if

*-----------------------------------------------------------------------

                     tlv = oldwt * dhet

! sumover
                  do ip = 1, ipn
                     tr0(ips(ip),i1,i2,it) =
     &               tr0(ips(ip),i1,i2,it) + tlv
                   enddo


        if (italsh .eq. 0 ) then
                  do ip = 1, ipn

                     tr(ips(ip),i1,i2,it,1) =
     &               tr(ips(ip),i1,i2,it,1) + tlv

                     tr(ips(ip),i1,i2,it,2) =
     &               tr(ips(ip),i1,i2,it,2) + tlv**2

                  end do

        else
!$OMP CRITICAL (tdpst2reg_crit)
                  do ip = 1, ipn

                     tr(ips(ip),i1,i2,it,1) =
     &               tr(ips(ip),i1,i2,it,1) + tlv

                     tr(ips(ip),i1,i2,it,2) =
     &               tr(ips(ip),i1,i2,it,2) + tlv**2

                  end do
!$OMP END CRITICAL (tdpst2reg_crit)
        endif
                  rrr = rrr - rrl

  270       continue

*-----------------------------------------------------------------------
*        normal case
*-----------------------------------------------------------------------

         else

                     tlv = oldwt * ( ein - ecc )
!sumover
                  do ip = 1, ipn
                     tr0(ips(ip),i1,i2,it) =
     &               tr0(ips(ip),i1,i2,it) + tlv
                  enddo


        if (italsh .eq. 0 ) then
                  do ip = 1, ipn

                     tr(ips(ip),i1,i2,it,1) =
     &               tr(ips(ip),i1,i2,it,1) + tlv

                     tr(ips(ip),i1,i2,it,2) =
     &               tr(ips(ip),i1,i2,it,2) + tlv**2

                  end do
        else
!$OMP CRITICAL (tdpst2reg_crit)
                  do ip = 1, ipn

                     tr(ips(ip),i1,i2,it,1) =
     &               tr(ips(ip),i1,i2,it,1) + tlv

                     tr(ips(ip),i1,i2,it,2) =
     &               tr(ips(ip),i1,i2,it,2) + tlv**2

                  end do
!$OMP END CRITICAL (tdpst2reg_crit)
        endif
         end if

*-----------------------------------------------------------------------

  200       continue

*-----------------------------------------------------------------------
*     dead particles of produced charged particle
*-----------------------------------------------------------------------

      if( ( ncol .eq. 13 .or. ncol .eq. 14 ) .and.
     &      mat .gt. 0 .and. nclsts .gt. 0 ) then

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( jcount(i,1) .lt. itcnt(i*2+2,m) .or.
     &                jcount(i,1) .gt. itcnt(i*2+3,m) ) goto 300

               end if

            end do

*-----------------------------------------------------------------------
*        dead particle and nucleus except for electron positron
*-----------------------------------------------------------------------

         do j = 1, nclsts

         if( jclusts(4,j) .lt. 0 .and. jclusts(5,j) .ne. 0 .and.
     &       qclusts(7,j) .gt. eletb(1) ) then


                  ipart = jclusts(3,j)
                  kpart = jclusts(7,j)
                  jpart = jclusts(5,j)
                  rpart = qclusts(5,j) * 1000.d0

*-----------------------------------------------------------------------

            call pcheck(m,np,ipart,kpart,jpart,ipn,ips)

               if( ipn .eq. 0 )  goto 285

*-----------------------------------------------------------------------

                  ein = qclusts(7,j)
                  ecc = 0.0d0

*-----------------------------------------------------------------------
*        dedxfnc is specified
*-----------------------------------------------------------------------

         if( itdfun .ne. 0 ) then

               if( ein .lt. eletb(1) ) goto 285

               do i = 1, nlete

                  if( ein .ge. eletb(i) .and.
     &                ein .lt. eletb(i+1) ) goto 35

               end do

   35             ie1 = min( i, nlete )
                  ie2 = 1

*-----------------------------------------------------------------------
*           rrl : track length and rrr : charge particles correction
*-----------------------------------------------------------------------

                  call rainge(ein,rng0,mat,
     &                        ipart,kpart,jpart,rpart)

c  T.Sato 2013/9/26 for counting stopped electron when it is created
c  This is temporary fixed version
           if(rng0.gt.1.d30.and.(ipart.eq.12.or.ipart.eq.13)) then
            dedx = 1.0  ! assuming that dE/dx = 1.0 keV/um
            dtrk = 0.0
            eini = ein
            efin = 0.0
            if( itdfun .eq. 1 ) then
             call usrdfn1(ipart,kpart,jpart,rpart,
     &                    dedx,dtrk,eini,efin,dhet)
            else if( itdfun .eq. 2 ) then
             call usrdfn2(ipart,kpart,jpart,rpart,
     &                    dedx,dtrk,eini,efin,dhet)
            end if
            tlv = qclusts(8,j) * dhet
! sumover
                  do ip = 1, ipn
                     tr0(ips(ip),i1,i2,it) =
     &               tr0(ips(ip),i1,i2,it) + tlv
                  enddo

            if (italsh .eq. 0 ) then
                  do ip = 1, ipn
                     tr(ips(ip),i1,i2,it,1) =
     &               tr(ips(ip),i1,i2,it,1) + tlv
                     tr(ips(ip),i1,i2,it,2) =
     &               tr(ips(ip),i1,i2,it,2) + tlv**2
                  end do
            else
!$OMP CRITICAL (tdpst2reg_crit)
                  do ip = 1, ipn
                     tr(ips(ip),i1,i2,it,1) =
     &               tr(ips(ip),i1,i2,it,1) + tlv
                     tr(ips(ip),i1,i2,it,2) =
     &               tr(ips(ip),i1,i2,it,2) + tlv**2
                  end do
!$OMP END CRITICAL (tdpst2reg_crit)
            endif
            goto 285
           endif
c  *******************************************************************

                  if( rng0 .gt. 1.d+30 ) goto 285

                  tlngth = rng0
                  rng1 = 0.0d0

                  rrl = tlngth
                  rrr = tlngth
                  rrt = 0.0d0

               if( ein .gt. eletb(nlete+1) ) then

                  call rainge(eletb(nlete+1),rngm,mat,
     &                        ipart,kpart,jpart,rpart)

                  rrr = max( 0.0d0, rrr - ( rng0 - rngm ) )
                  rrt = rrt + rng0 -rngm

               end if

*-----------------------------------------------------------------------
*           tally
*-----------------------------------------------------------------------

            do 275 ie = ie1, ie2, -1

                     emie = max( ecc, eletb(ie) )
                     emiu = min( ein, eletb(ie+1) )

                  if( emiu * emie .gt. 0.d0 ) then
                     erg  = sqrt( emiu * emie )
                  else
                     erg  = emiu / 2.d0
                  end if

                  if( mat .gt. 0 ) then

                     call rainge(emie,rng,mat,
     &                           ipart,kpart,jpart,rpart)

                     rng = max( 0.0d0, rng - rng1 )
                     rrl = max( 0.0d0, rrr - rng )

                        rrt  = rrt + rrl

                     if( rrt .gt. tlngth ) then

                        rrl = rrl + ( tlngth - rrt )
                        rrt = tlngth

                     else if( ie .eq. ie2 .and.
     &                        ecc .gt. eletb(ie) ) then

                        rrl = rrl + ( tlngth - rrt )

                     end if

                  end if

*-----------------------------------------------------------------------
*              dedx value multiplyed user factor
*-----------------------------------------------------------------------

               call dedxas(erg,dedx,lmat,ipart,kpart,jpart,rpart)

                  dedx = dedx / 10.d0
                  dtrk = rrl
                  eini = emiu
                  efin = emie

               if( itdfun .eq. 1 ) then

                  call usrdfn1(ipart,kpart,jpart,rpart,
     &                         dedx,dtrk,eini,efin,dhet)

               else if( itdfun .eq. 2 ) then

                  call usrdfn2(ipart,kpart,jpart,rpart,
     &                         dedx,dtrk,eini,efin,dhet)

               end if

*-----------------------------------------------------------------------

                     tlv = qclusts(8,j) * dhet
! sumover
                  do ip = 1, ipn
                     tr0(ips(ip),i1,i2,it) =
     &               tr0(ips(ip),i1,i2,it) + tlv
                  enddo

            if (italsh .eq. 0 ) then
                  do ip = 1, ipn

                     tr(ips(ip),i1,i2,it,1) =
     &               tr(ips(ip),i1,i2,it,1) + tlv

                     tr(ips(ip),i1,i2,it,2) =
     &               tr(ips(ip),i1,i2,it,2) + tlv**2

                  end do
            else
!$OMP CRITICAL (tdpst2reg_crit)
                  do ip = 1, ipn

                     tr(ips(ip),i1,i2,it,1) =
     &               tr(ips(ip),i1,i2,it,1) + tlv

                     tr(ips(ip),i1,i2,it,2) =
     &               tr(ips(ip),i1,i2,it,2) + tlv**2

                  end do
!$OMP END CRITICAL (tdpst2reg_crit)
            endif
                  rrr = rrr - rrl

  275       continue

*-----------------------------------------------------------------------
*        normal case
*-----------------------------------------------------------------------

         else

                     tlv = qclusts(8,j) * ( ein - ecc )
! sumover
                  do ip = 1, ipn
                     tr0(ips(ip),i1,i2,it) =
     &               tr0(ips(ip),i1,i2,it) + tlv
                  enddo


            if (italsh .eq. 0 ) then
                  do ip = 1, ipn

                     tr(ips(ip),i1,i2,it,1) =
     &               tr(ips(ip),i1,i2,it,1) + tlv

                     tr(ips(ip),i1,i2,it,2) =
     &               tr(ips(ip),i1,i2,it,2) + tlv**2

                  end do
            else
!$OMP CRITICAL (tdpst2reg_crit)
                  do ip = 1, ipn

                     tr(ips(ip),i1,i2,it,1) =
     &               tr(ips(ip),i1,i2,it,1) + tlv

                     tr(ips(ip),i1,i2,it,2) =
     &               tr(ips(ip),i1,i2,it,2) + tlv**2

                  end do
!$OMP END CRITICAL (tdpst2reg_crit)
           end if
         end if

*-----------------------------------------------------------------------

  285       continue

         end if
         end do

*-----------------------------------------------------------------------

  300    continue

      end if

*-----------------------------------------------------------------------

 1000 continue

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine pdpst2reg(m,np,nr,mr,ne1,ne2,nt,kr,eb1,eb2,tb,tr,
     &                     nvl,ivl,rvl,idasa)
*                                                                      *
*       output the Deposit2 tally in region mesh                       *
*       last modified by K.Niita on 2005/12/22                         *
*                                                                      *
************************************************************************
       use sumtallymod , only : isumtally
      use sangelmod, only: itsans
      use partmod ! frtati 2021/10/05

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param.inc'

*-----------------------------------------------------------------------

      common /taliin/ rsouin, nzztin, nrgnin

*-----------------------------------------------------------------------

      common /verjam/ versn, lastr, iyeav, imonv, idayv

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)

      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)

      common /tall56/ itety2(itlmax), itenm2(itlmax), iterg2(itlmax),
     &                rtemi2(itlmax), rtema2(itlmax), rtedl2(itlmax)

      common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &                rttmi(itlmax), rttma(itlmax), rttdl(itlmax)

      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80
      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall21/ rtfac(itlmax)
      common /tall35/ iteps(itlmax)

      common /istcut/ ist_cut, ist_bat

      common /fact01/ facmax(itlmax) ! kitamura23/03/31

*-----------------------------------------------------------------------

      common /tcntl/  icntl, inucr

*-----------------------------------------------------------------------

      common /cparm/  maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

      common /talout/ itall

      character fname*100, fnume*3

      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /mpi00/ npe, me

*-----------------------------------------------------------------------

      dimension   kr(mr)
      dimension   eb1(ne1+1)
      dimension   eb2(ne2+1)
      dimension   tb(nt+1)
      dimension   tw(nt)
      dimension   tr(np,0:ne1,0:ne2,nt,2)
      dimension   vl(nr)
      dimension   lr(nr)
      dimension   ivl(nvl)
      dimension   rvl(nvl)

*-----------------------------------------------------------------------

      dimension tott(np,2) ! frtati 2021/10/05 6 -> np

      character hsunit(2)*23

      data hsunit( 1) / 'Number [1/source]     '/
      data hsunit( 2) / 'Number [1/nsec/source]'/

      character cha*1
      data cha /"'"/

cfrtati 2021/10/05 chl, chm moved to partmod

      character dc2*4
cfrtati 2021/10/05 6 -> itmxpt
      character chp(itmxpt)*11  ! kitamura22/03/31
      character chq(itmxpt)*9   ! kitamura22/03/31


      character rpa*1
      data rpa /'}'/
      character yen*1
      include 'samepage_include/samepage000.inc'

      include 'samepage_include/samepage001.inc'

      yen  = char(92)

*-----------------------------------------------------------------------
      np_mxang = np
      if ( itmxang(m).ne.0 .and. iabs(itmxang(m)).lt.np ) then
        np_mxang = iabs(itmxang(m))
      end if

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

               call wtpname(m,np,chp,chq)

*-----------------------------------------------------------------------
*           itunt(m) = 1 : 1/source
*-----------------------------------------------------------------------
*        set mesh volume and name
*-----------------------------------------------------------------------

               call tregvl(nr,mr,kr,vl,lr,nvl,ivl,rvl)

*-----------------------------------------------------------------------
*        ( unit = 1, 2 ; vol = 1.0 )
*-----------------------------------------------------------------------

             vl_sum = sum(vl(:))
            if( itunt(m) .eq. 1 .or. itunt(m) .eq. 2 ) then

               do ir = 1, nr

                  vl(ir) = 1.0d0

               end do
               vl_sum = 1.0d0

            end if

*-----------------------------------------------------------------------
*           itunt(m) = 2 : /nsec
*-----------------------------------------------------------------------

            if( itunt(m) .eq. 2 ) then

               do i = 1, nt

                  tw(i) = tb(i+1) - tb(i)

               end do
               tw_sum = tb(nt+1) - tb(1)

            else

               do i = 1, nt

                  tw(i) = 1.d+0

               end do
               tw_sum = 1.0d0

            end if

*-----------------------------------------------------------------------
*        relative error and  unit conversion
*        c1 : normalization for source
*-----------------------------------------------------------------------

                  cmax = 0.0
                  cmin = 1.e+33
                  dnon = 1.e-33
                  isdz = 0
                  stdm = 0.0
                  itstd(m) = 1

                if( isumtally(m)/=2 ) then
                 if ( rsouin .gt. 0d0 ) then ! S.H. (2016.7.26)
                  c1 = 1.0d+0 / rsouin
                 else
                  c1 = 0d0
                 end if
                else
                  c1 = 1.0d+0
                end if

            facmax(m) = 1.d0
            if( rtfac(m) .lt. 0.d0 ) then
               facmax(m) = 0.d0

               do 101 ie1 = 1, ne1
               do 101 ie2 = 1, ne2
               do 101 it  = 1, nt
               do 101 ip  = 1, np

                  if( isumtally(m)/=2 ) then

                     if( tr(ip,ie1,ie2,it,1) .gt. 0.d0 ) then

                        fmaxfc = tr(ip,ie1,ie2,it,1) / vl(1)

                        if( facmax(m) .lt. fmaxfc) facmax(m) = fmaxfc

                     end if

                  end if

  101          continue

            end if

            do 100 ie1 = 1, ne1
            do 100 ie2 = 1, ne2
            do 100 it  = 1, nt
            do 100 ip  = 1, np

             if( isumtally(m)/=2 ) then   ! Weighted average calculation

               if( tr(ip,ie1,ie2,it,1) .gt. 0.d0 ) then

                  call calc_deposit_stdev(m,Xa,sigx,
     &                            tr(ip,ie1,ie2,it,1),
     &                            tr(ip,ie1,ie2,it,2),
     &             abs(rtfac(m)/facmax(m))/vl(1),ip)

                  tr(ip,ie1,ie2,it,1) = Xa
                  tr(ip,ie1,ie2,it,2) = sigx
                  if( sigx .gt. stdm ) stdm = sigx

                  if( tr(ip,ie1,ie2,it,1) .gt. cmax )
     &                        cmax = tr(ip,ie1,ie2,it,1)

                  if( tr(ip,ie1,ie2,it,1) .lt. cmin )
     &                        cmin = tr(ip,ie1,ie2,it,1)

               else

                  isdz = 1
                  tr(ip,ie1,ie2,it,2) = 0.0

               end if
             else
               if( tr(ip,ie1,ie2,it,1) .gt. 0.d0 ) then
                 if( tr(ip,ie1,ie2,it,1) .gt. cmax )
     &                    cmax = tr(ip,ie1,ie2,it,1)
                 if( tr(ip,ie1,ie2,it,1) .lt. cmin )
     &                   cmin = tr(ip,ie1,ie2,it,1)
               else
                 isdz = 1
                 tr(ip,ie1,ie2,it,2) = 0.0
               endif
             end if
! sumover
             if( isumtally(m)/=2 ) then   ! Weighted average calculation
             fact_in = abs(rtfac(m)/facmax(m))
             call pdpst2reg_sumover_stdev(0,m,ip,ie1,ie2,it,
     &                1,1,
     &                fact_in,1.0d0,1.0d0,vl(1),1.0d0,vl(1))
             endif


  100       continue

            if( nobch .gt. ist_bat ) then
            if( rtstd(m) .gt. 0.d0 .and.
     &          stdm .gt. 0.d0 .and. isdz .eq. 0 .and.
     &          stdm .lt. rtstd(m) ) itstd(m) = 0
            end if

*-----------------------------------------------------------------------
*     out put unit = 31  : temporary number
*-----------------------------------------------------------------------

      do 900 iax = 1, itfln(m)

!OBINATA(2012.9.20): output *.err
        noe = 1
        if ( any( itaxs(m,iax) .eq. (/ 3, 4, 5, 6, 7, 8 /) )
     &      .and. ittwo(m) .ne. 4 .and. icntl .ne. 8 )
     &    noe = 2

        do 900 ioe = 1, noe

         if( itall .eq. 2 .and. nobch .lt. maxbch ) then

            write(fnume,'(i3.3)') nobch
!OBINATA(2012.9.20): output *.err
            if ( ioe .eq. 1 ) then
              fname = ctfln(m,iax)(1:itfll(m,iax))//'.'//fnume
            else
              call mk_2derrfn(ctfln(m,iax),fname,itfll(m,iax))
            end if

            else if ( itall.eq.4 ) then
              write(fnume,'(i3.3)') nobch
              if ( npe.gt.1 ) write (fnume,'(i3.3)') nobch/(npe-1)
              if ( ioe.eq.1 ) then
                call mk_2dnumfn(ctfln(m,iax),fname,itfll(m,iax),
     &               nobch,maxbch,npe)
              else
                call mk_2dnerfn(ctfln(m,iax),fname,itfll(m,iax),fnume)
              end if

         else

!OBINATA(2012.9.20): output *.err
            if ( ioe .eq. 1 ) then
              fname = ctfln(m,iax)
            else
              call mk_2derrfn(ctfln(m,iax),fname,itfll(m,iax))
            end if

         end if

            iot = 31
            open(iot, file = fname, status = 'unknown' )

*-----------------------------------------------------------------------
*     input echo
*-----------------------------------------------------------------------

               call dps2tech(iot,m,iax,1)


      include 'samepage_include/samepage002_pe1e2t.inc'
      include 'samepage_include/samepagechp_pe1e2t.inc'
      include 'samepage_include/samepageseti.inc'

*-----------------------------------------------------------------------
*        eng1 axis for deposit energy distribution
*-----------------------------------------------------------------------

         if( itaxs(m,iax) .eq. 1 ) then

               inum = 0

            do ie2i = 1, ne2, ne2stepi
            do iti  = 1, nt, ntstepi
            do ipi  = 1, np, npstepi
               ie2 = ie2i
               it = iti
               ip = ipi

               inum = inum + 1

                  write(iot,'(/"#",78("-"))')

               if( inum .eq. 1 ) then
                  write(iot,'( "#newpage:")')
               else
                  write(iot,'( " newpage:")')
               end if

               if( rtfac(m) .lt. 0.d0 )
     &           write(iot,
     &           '( "#restart maximum for normalization:",1p1e14.7)')
     &           facmax(m)

               if(iloopmode .ge. 1) then
                  write(iot,'("#   ",a)') chp(ipi)(3:10)
               endif

                  write(iot,'("#   no. =",i3/
     &            "# ie2 =",i3,/
     &            "#  e2 = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                        inum, ie2,
     &                        eb2(ie2), eb2(ie2+ne2stepi)

               if( ittty(m) .ne. 0 ) then
                  write(iot,'(
     &            "#  it =",i3/
     &            "#   t = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                  it, tb(it), tb(it+ntstepi)
               end if

               if( itaxl(m) .eq. 0 ) then

                  write(iot,'(/"x: Deposit Energy of Reg 1 [MeV]")')

               else

                  write(iot,'(/"x: ",200a1)')
     &                       (itaxt(m)(i:i),i=1,itaxl(m))

               end if

               if( itayl(m) .eq. 0 ) then

                  write(iot,'( "y: ",a18)') hsunit(itunt(m))

               else

                  write(iot,'( "y: ",200a1)')
     &                       (itayt(m)(i:i),i=1,itayl(m))

               end if

               if( itety(m) .eq. 3 .or. itety(m) .eq. 5 ) then

                  write(iot,'( "p: xlog ylog afac(0.8) form(0.9)")')

               else

                  write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

               end if

               if( itanl(m) .gt. 0 ) then

                  write(iot,'( "p: ",200a1)')
     &            ( itang(m)(i:i),i = 1, itanl(m) )

               end if

               if( itsans(m) .gt. 0 ) then

                  call write_sangel(iot,m,0)

               end if

       include 'samepage_include/pe1e2t_e1.inc'

*-----------------------------------------------------------------------

             if(iloopmode .eq. 0) then
               if( ittty(m) .eq. 0  ) then
                     write(iot,'(/a1,"no. =",i3,", ie2 =",
     &                     i3,a1)')
     &                     cha, inum, ie2, cha
               else
                     write(iot,'(/a1,"no. =",i3,", ie2 =",
     &                     i3,", it =",i3,a1)')
     &                     cha, inum, ie2, it, cha
               end if
             else
                write(changelsub(1),'(a1,"no. =",i3)') cha,inum
                write(changelsub(2),'(",  part = ",a)') chp(ipi)(3:10)
                write(changelsub(3),'(",  ie1 =",i3)') ie1
                write(changelsub(4),'(",  ie2 =",i3)') ie2
                write(changelsub(5),'(",  it =",i3)') it
                write(changelsub(6),'(a1)') cha

               if( ittty(m) .eq. 0  ) then
                 changelsub(5) = " "
               end if
               changelsub(3) = " "
               if(iloopmode .eq. 10) then
                  changelsub(5) = " "
               end if
               if(iloopmode .eq. 12) then
                  changelsub(3) = " "
               end if
               if(iloopmode .eq. 13) then
                  changelsub(4) = " "
               end if
                angeltitle = trim(changelsub(1))//trim(changelsub(2))//
     &                       trim(changelsub(3))//trim(changelsub(4))//
     &                       trim(changelsub(5))//trim(changelsub(6))
                write(iot,'(/a)') trim(angeltitle)
          end if

                     write(iot,'("wt: s(0.7)",/
     &                     a1,"vspace{-3}"/
     &                     "  emin2 &=&",1pe13.4," [MeV]"/
     &                     "  emax2 &=&",1pe13.4," [MeV]")')
     &                     yen, eb2(ie2), eb2(ie2+ne2stepi)
               if( ittty(m) .ne. 0 ) then
                     write(iot,'(
     &                     "  tmin  &=&",1pe13.4," [nsec]"/
     &                     "  tmax  &=&",1pe13.4," [nsec]")')
     &                     tb(it), tb(it+ntstepi)
               end if

                     write(iot,'("e:")')

               write(iot,'("msuc: {",a1,"huge ",80a1)')
     &                  yen, ( ittle(m)(i:i), i = 1, ittll(m) ), rpa

               write(iot,'("msdr: {",a1,"it plotted by ",
     &                  a1,"ANGEL ",a1,"version}")') yen, yen, yen
               write(iot,'("msdl: {",a1,"it calculated by ",
     &                  a1,"PHITS ",f5.2"}")') yen, yen, versn

               if(iloopmode .ge. 1) then
                     write(iot,'("wt: s(0.7)",/
     &                     a1,"vspace{-3}")') yen
                     write(iot,'("  part  &=& ",a)') chp(ipi)(3:10)
                     write(iot,'("e:")')
               endif

            end do

            end do
            end do

*-----------------------------------------------------------------------
*        eng2 axis for deposit energy distribution
*-----------------------------------------------------------------------

         else if( itaxs(m,iax) .eq. 2 ) then

               inum = 0

            do ie1i = 1, ne1, ne1stepi
            do iti  = 1, nt, ntstepi
            do ipi  = 1, np, npstepi
               ie1 = ie1i
               it  = iti
               ip =  ipi

               inum = inum + 1

                  write(iot,'(/"#",78("-"))')

               if( inum .eq. 1 ) then
                  write(iot,'( "#newpage:")')
               else
                  write(iot,'( " newpage:")')
               end if

               if( rtfac(m) .lt. 0.d0 )
     &           write(iot,
     &           '( "#restart maximum for normalization:",1p1e14.7)')
     &           facmax(m)

               if(iloopmode .ge. 1) then
                  write(iot,'("#   ",a)') chp(ipi)(3:10)
               endif

                  write(iot,'("#   no. =",i3/
     &            "# ie1 =",i3,/
     &            "#  e1 = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                        inum, ie1,
     &                        eb1(ie1), eb1(ie1+ne1stepi)

               if( ittty(m) .ne. 0 ) then
                  write(iot,'(
     &            "#  it =",i3/
     &            "#   t = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                  it, tb(it), tb(it+ntstepi)
               end if

               if( itaxl(m) .eq. 0 ) then

                  write(iot,'(/"x: Deposit Energy of Reg 2 [MeV]")')

               else

                  write(iot,'(/"x: ",200a1)')
     &                       (itaxt(m)(i:i),i=1,itaxl(m))

               end if

               if( itayl(m) .eq. 0 ) then

                  write(iot,'( "y: ",a18)') hsunit(itunt(m))

               else

                  write(iot,'( "y: ",200a1)')
     &                       (itayt(m)(i:i),i=1,itayl(m))

               end if

               if( itety(m) .eq. 3 .or. itety(m) .eq. 5 ) then

                  write(iot,'( "p: xlog ylog afac(0.8) form(0.9)")')

               else

                  write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

               end if

               if( itanl(m) .gt. 0 ) then

                  write(iot,'( "p: ",200a1)')
     &            ( itang(m)(i:i),i = 1, itanl(m) )

               end if

               if( itsans(m) .gt. 0 ) then

                  call write_sangel(iot,m,0)

               end if

       include 'samepage_include/pe1e2t_e2.inc'

*-----------------------------------------------------------------------

             if(iloopmode .eq. 0) then
               if( ittty(m) .eq. 0  ) then
                     write(iot,'(/a1,"no. =",i3,", ie1 =",
     &                     i3,a1)')
     &                     cha, inum, ie1, cha
               else
                     write(iot,'(/a1,"no. =",i3,", ie1 =",
     &                     i3,", it =",i3,a1)')
     &                     cha, inum, ie1, it, cha
               end if
             else
                write(changelsub(1),'(a1,"no. =",i3)') cha,inum
                write(changelsub(2),'(",  part = ",a)') chp(ipi)(3:10)
                write(changelsub(3),'(",  ie1 =",i3)') ie1
                write(changelsub(4),'(",  ie2 =",i3)') ie2
                write(changelsub(5),'(",  it =",i3)') it
                write(changelsub(6),'(a1)') cha

               if( ittty(m) .eq. 0  ) then
                 changelsub(5) = " "
               end if
               changelsub(4) = " "
               if(iloopmode .eq. 10) then
                  changelsub(5) = " "
               end if
               if(iloopmode .eq. 12) then
                  changelsub(3) = " "
               end if
               if(iloopmode .eq. 13) then
                  changelsub(4) = " "
               end if
                angeltitle = trim(changelsub(1))//trim(changelsub(2))//
     &                       trim(changelsub(3))//trim(changelsub(4))//
     &                       trim(changelsub(5))//trim(changelsub(6))
                write(iot,'(/a)') trim(angeltitle)
          end if

                     write(iot,'("wt: s(0.7)",/
     &                     a1,"vspace{-3}"/
     &                     "  emin1 &=&",1pe13.4," [MeV]"/
     &                     "  emax1 &=&",1pe13.4," [MeV]")')
     &                     yen, eb1(ie1), eb1(ie1+ne1stepi)
               if( ittty(m) .ne. 0 ) then
