************************************************************************
*                                                                      *
      subroutine tletreg_sumover(m,maxcas,
     &                   np,  ne, nr,tr0x)
*     tr_sum(np,ne,nr,2)                                               *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nr)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
        if(n_tr_sum > 0) then

          call tletreg_sumover_sub(maxcas,itaxs(m,iax),
     &      np,  ne, nr, tr0x,
     &      itpan_sum(m,iax),itenm_sum(m,iax),
     &      itrgn_sum(m,iax),
     &      tr_sum)

        endif

      enddo

      return
      end


************************************************************************
*                                                                      *
      subroutine tletreg_sumover_sub(maxcas_in,itaxs_in,
     &           np,  ne, nr, tr0,
     &           np_sum,  ne_sum, nr_sum,
     &           tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,ne,nr)
      dimension   tr_sum(np_sum,ne_sum,nr_sum,2)

      maxcas = maxcas_in
      if(maxcas_in == 0) then
         maxcas = 1
      endif

      if(itaxs_in == 1) then  ! energ
        do ir = 1,nr
        do ip = 1,np

          tr0_sum = 0.0d0
          do ie = 1,ne
            tr0_sum = tr0_sum + tr0(ip,ie,ir) / maxcas
          end do
          tr_sum(ip,1,ir,1) =
     &           tr_sum(ip,1,ir,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,1,ir,2) = tr_sum(ip,1,ir,2) + 1.0d0
           else
            tr_sum(ip,1,ir,2) =
     &           tr_sum(ip,1,ir,2) + tr0_sum ** 2
          endif
        end do
        end do
!

      elseif(itaxs_in == 2) then    ! r
        do ie = 1,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do ir = 1,nr
            tr0_sum = tr0_sum + tr0(ip,ie,ir) / maxcas
          end do
          tr_sum(ip,ie,1,1) =
     &           tr_sum(ip,ie,1,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,1,2) = tr_sum(ip,ie,1,2) + 1.0d0
          else
            tr_sum(ip,ie,1,2) =
     &           tr_sum(ip,ie,1,2) + tr0_sum ** 2
          endif
        end do
        end do

       end if
       return
       end


************************************************************************
*                                                                      *
      subroutine pletreg_sumover_stdev(mode,m,ip,ie,ir,
     &                fact_in,ew,vl,ew_sum,vl_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

       if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
       else

          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

       endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/vl/ew
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 2 .and. ir == 1) then
             sum_fact = sum_fact * vl / vl_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pletreg_sumover_stdev_sub(mode,m,sum_fact,ip,ie,ir,
     &         itpan_sum(m,iax),itenm_sum(m,iax),itrgn_sum(m,iax),
     &         tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pletreg_sumover_stdev_ntf(mode,m,ntf,ip,ie,ir,
     &                fact_in,ew,vl,ew_sum,vl_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

       if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM_NTF(tr_sum,m,ntf,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM_NTF(tr_sum,m,ntf,iax)
C for nonshared_tally option
!$       end if
       else

          ntfbase = mtalsize_sum(m) * (ntf-1)
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax)+ntfbase:)

       endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/vl/ew
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 2 .and. ir == 1) then
             sum_fact = sum_fact * vl / vl_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pletreg_sumover_stdev_sub(mode,m,sum_fact,ip,ie,ir,
     &         itpan_sum(m,iax),itenm_sum(m,iax),itrgn_sum(m,iax),
     &         tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pletreg_sumover_stdev_sub(mode,m,sum_fact,ip,ie,ir,
     &                   np_sum,ne_sum,nr_sum,
     &                   tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension tr_sum(np_sum,ne_sum,nr_sum,2)

      if(tr_sum(ip,ie,ir,1) > 0.0) then
        if(mode == 0) then
                  call calc_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie,ir,1),
     &                            tr_sum(ip,ie,ir,2),
     &                            sum_fact)
        else
                  sum_fact_r = 1.0d0 / sum_fact
                  call invert_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie,ir,1),
     &                            tr_sum(ip,ie,ir,2),
     &                            sum_fact_r)
        endif
                  tr_sum(ip,ie,ir,1) = Xa
                  tr_sum(ip,ie,ir,2) = sigx

      else

        tr_sum(ip,ie,ir,2) = 0.0

      end if

      return
      end

************************************************************************
*                                                                      *
      subroutine  pletreg_sumover_getput(mode,m,iax,
     &    npstepi,nestepi,nrstepi,
     &    ipi,iei,iri,maxtott,tott_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      real(8) :: tott_sum(maxtott,2)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

      real(8),pointer :: tr_sum(:)

      real(8),allocatable :: tott_in(:,:)
      character :: chin*200

      if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

         call pletreg_sumover_getput_sub(mode,
     &    npstepi,nestepi,nrstepi,
     &    ipi,iei,iri,maxtott,tott_sum,
     &    itpan_sum(m,iax),itenm_sum(m,iax),itrgn_sum(m,iax),
     &    tr_sum)

      else
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

          nsame = npstepi * nestepi * nrstepi
          allocate (tott_in(nsame,2))

          read(mode,'(a)') chin
          read(mode,'(26x,1000(1pe13.4,0pf8.4))')
     &    (tott_in(i,1),tott_in(i,2),i=1,nsame)

          call pletreg_sumover_getput_sub(mode,
     &    npstepi,nestepi,nrstepi,
     &    ipi,iei,iri,nsame,tott_in,
     &    itpan_sum(m,iax),itenm_sum(m,iax),itrgn_sum(m,iax),
     &    tr_sum)

          deallocate (tott_in)

      endif
      return
      end

************************************************************************
*                                                                      *
      subroutine pletreg_sumover_getput_sub(mode,
     &    npstepi,nestepi,nrstepi,
     &    ipi,iei,iri,maxtott,tott_sum,
     &    np_sum,ne_sum,nr_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(np_sum,ne_sum,nr_sum,2)

      real(8) :: tott_sum(maxtott,2)

        i = 0
            do irloop=1,nrstepi
              do ieloop=1,nestepi
                do iploop=1,npstepi
                  i = i + 1
                  do k=1,2
                    if(mode == 0) then
                      tott_sum(i,k) =
     &                tr_sum(ipi+iploop-1,iei+ieloop-1,iri+irloop-1,k)
                    else
                      tr_sum(ipi+iploop-1,iei+ieloop-1,iri+irloop-1,k)
     &                = tott_sum(i,k)
                    endif
                  enddo
                end do
              end do
            end do

      return
      end

************************************************************************
*                                                                      *
      subroutine tletrz_sumover(m,maxcas,
     &                   np,  ne, nr, nz, tr0x)
*     tr_sum(np,ne,nr,nz,2)                                               *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nr,nz)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
        if(n_tr_sum > 0) then

          call tletrz_sumover_sub(maxcas,itaxs(m,iax),
     &      np,  ne, nr, nz, tr0x,
     &      itpan_sum(m,iax),itenm_sum(m,iax),
     &      itrnm_sum(m,iax),itznm_sum(m,iax),
     &      tr_sum)

        endif

      enddo

      return
      end


************************************************************************
*                                                                      *
      subroutine tletrz_sumover_sub(maxcas_in,itaxs_in,
     &           np,  ne, nr, nz, tr0,
     &           np_sum,  ne_sum, nr_sum, nz_sum,
     &           tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,ne,nr,nz)
      dimension   tr_sum(np_sum,ne_sum,nr_sum,nz_sum,2)

      maxcas = maxcas_in
      if(maxcas_in == 0) then
         maxcas = 1
      endif

      if(itaxs_in == 1) then  ! energ
        do iz = 1,nz
        do ir = 1,nr
        do ip = 1,np

          tr0_sum = 0.0d0
          do ie = 1,ne
            tr0_sum = tr0_sum + tr0(ip,ie,ir,iz) / maxcas
          end do
          tr_sum(ip,1,ir,iz,1) =
     &           tr_sum(ip,1,ir,iz,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,1,ir,iz,2) = tr_sum(ip,1,ir,iz,2) + 1.0d0
           else
            tr_sum(ip,1,ir,iz,2) =
     &           tr_sum(ip,1,ir,iz,2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
!
      elseif(itaxs_in == 5) then    ! z
        do ir = 1,nr
        do ie = 1,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do iz = 1,nz
            tr0_sum = tr0_sum + tr0(ip,ie,ir,iz) / maxcas
          end do
          tr_sum(ip,ie,ir,1,1) =
     &           tr_sum(ip,ie,ir,1,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,ir,1,2) = tr_sum(ip,ie,ir,1,2) + 1.0d0
          else
            tr_sum(ip,ie,ir,1,2) =
     &           tr_sum(ip,ie,ir,1,2) + tr0_sum ** 2
          endif
        end do
        end do
        end do

      elseif(itaxs_in == 6) then    ! r
        do iz = 1,nz
        do ie = 1,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do ir = 1,nr
            tr0_sum = tr0_sum + tr0(ip,ie,ir,iz) / maxcas
          end do
          tr_sum(ip,ie,1,iz,1) =
     &           tr_sum(ip,ie,1,iz,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,1,iz,2) = tr_sum(ip,ie,1,iz,2) + 1.0d0
          else
            tr_sum(ip,ie,1,iz,2) =
     &           tr_sum(ip,ie,1,iz,2) + tr0_sum ** 2
          endif
        end do
        end do
        end do

       end if
       return
       end


************************************************************************
*                                                                      *
      subroutine pletrz_sumover_stdev(mode,m,ip,ie,ir,iz,
     &                fact_in,ew,vl,ew_sum,vl_r,vl_z)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

       if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

       else
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

       endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/vl/ew
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 5 .and. iz == 1) then
             sum_fact = sum_fact * vl / vl_z
          else if(itaxs(m,iax) == 6 .and. ir == 1) then
             sum_fact = sum_fact * vl / vl_r
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pletrz_sumover_stdev_sub(mode,m,sum_fact,ip,ie,ir,iz,
     &         itpan_sum(m,iax),itenm_sum(m,iax),itrnm_sum(m,iax),
     &         itznm_sum(m,iax),tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pletrz_sumover_stdev_ntf(mode,m,ntf,ip,ie,ir,iz,
     &                fact_in,ew,vl,ew_sum,vl_r,vl_z)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

       if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM_NTF(tr_sum,m,ntf,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM_NTF(tr_sum,m,ntf,iax)
C for nonshared_tally option
!$       end if

       else
          ntfbase = mtalsize_sum(m) * (ntf-1)
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax)+ntfbase:)

       endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/vl/ew
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 5 .and. iz == 1) then
             sum_fact = sum_fact * vl / vl_z
          else if(itaxs(m,iax) == 6 .and. ir == 1) then
             sum_fact = sum_fact * vl / vl_r
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pletrz_sumover_stdev_sub(mode,m,sum_fact,ip,ie,ir,iz,
     &         itpan_sum(m,iax),itenm_sum(m,iax),itrnm_sum(m,iax),
     &         itznm_sum(m,iax),tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pletrz_sumover_stdev_sub(mode,m,sum_fact,ip,ie,ir,iz,
     &                   np_sum,ne_sum,nr_sum,nz_sum,
     &                   tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension tr_sum(np_sum,ne_sum,nr_sum,nz_sum,2)

      if(tr_sum(ip,ie,ir,iz,1) > 0.0) then

         if( mode == 0) then
                  call calc_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie,ir,iz,1),
     &                            tr_sum(ip,ie,ir,iz,2),
     &                            sum_fact)
         else
                  sum_fact_r = 1.0d0 / sum_fact
                  call invert_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie,ir,iz,1),
     &                            tr_sum(ip,ie,ir,iz,2),
     &                            sum_fact_r)
         endif

                  tr_sum(ip,ie,ir,iz,1) = Xa
                  tr_sum(ip,ie,ir,iz,2) = sigx

      else

        tr_sum(ip,ie,ir,iz,2) = 0.0

      end if

      return
      end

************************************************************************
*                                                                      *
      subroutine  pletrz_sumover_getput(mode,m,iax,
     &    npstepi,nestepi,nrstepi,nzstepi,
     &    ipi,iei,iri,izi,maxtott,tott_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      real(8) :: tott_sum(maxtott,2)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

      real(8),pointer :: tr_sum(:)

      real(8), allocatable :: tott_in(:,:)
      character :: chin*200


       if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

         call pletrz_sumover_getput_sub(mode,
     &    npstepi,nestepi,nrstepi,nzstepi,
     &    ipi,iei,iri,izi,maxtott,tott_sum,
     &    itpan_sum(m,iax),itenm_sum(m,iax),itrnm_sum(m,iax),
     &    itznm_sum(m,iax),tr_sum)

      else
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

          nsame = npstepi * nestepi * nrstepi * nzstepi
          allocate (tott_in(nsame,2))

          read(mode,'(a)') chin
          read(mode,'(26x,1000(1pe13.4,0pf8.4))')
     &    (tott_in(i,1),tott_in(i,2),i=1,nsame)

         call pletrz_sumover_getput_sub(mode,
     &    npstepi,nestepi,nrstepi,nzstepi,
     &    ipi,iei,iri,izi,nsame,tott_in,
     &    itpan_sum(m,iax),itenm_sum(m,iax),itrnm_sum(m,iax),
     &    itznm_sum(m,iax),tr_sum)

          deallocate (tott_in)

      endif

      return
      end

************************************************************************
*                                                                      *
      subroutine pletrz_sumover_getput_sub(mode,
     &    npstepi,nestepi,nrstepi,nzstepi,
     &    ipi,iei,iri,izi,maxtott,tott_sum,
     &    np_sum,ne_sum,nr_sum,nz_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(np_sum,ne_sum,nr_sum,nz_sum,2)

      real(8) :: tott_sum(maxtott,2)

        i = 0
          do izloop=1,nzstepi
            do irloop=1,nrstepi
              do ieloop=1,nestepi
                do iploop=1,npstepi
                  i = i + 1
                  do k=1,2
                    if(mode == 0) then
                      tott_sum(i,k) =
     &                tr_sum(ipi+iploop-1,iei+ieloop-1,iri+irloop-1,
     &                izi+izloop-1,k)
                    else
                      tr_sum(ipi+iploop-1,iei+ieloop-1,iri+irloop-1,
     &                izi+izloop-1,k)
     &                = tott_sum(i,k)
                    endif
                  enddo
                end do
              end do
            end do
          end do

      return
      end

************************************************************************
*                                                                      *
      subroutine tletxyz_sumover(m,maxcas,
     &                   np,  ne, nx, ny, nz, tr0x)
*     tr_sum(np,ne,nx*ny*nz,2)                                         *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nx*ny*nz)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
        if(n_tr_sum > 0) then

          call tletxyz_sumover_sub(maxcas,itaxs(m,iax),
     &      np,  ne, nx, ny, nz, tr0x,
     &      itpan_sum(m,iax),itenm_sum(m,iax),
     &      itxnm_sum(m,iax),itynm_sum(m,iax),itznm_sum(m,iax),
     &      tr_sum)

        endif

      enddo

      return
      end


************************************************************************
*                                                                      *
      subroutine tletxyz_sumover_sub(maxcas_in,itaxs_in,
     &           np,  ne, nx, ny, nz, tr0,
     &           np_sum,  ne_sum, nx_sum, ny_sum, nz_sum,
     &           tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,ne,nx*ny*nz)
      dimension   tr_sum(np_sum,ne_sum,nx_sum*ny_sum*nz_sum,2)

      icf(ix,iy,iz) = ix + ( iy - 1 ) * nx + ( iz - 1 ) * nx * ny
      icf_sum(ix,iy,iz) = ix + ( iy - 1 ) * nx_sum
     &                   + ( iz - 1 ) * nx_sum * ny_sum


      maxcas = maxcas_in
      if(maxcas_in == 0) then
         maxcas = 1
      endif

      if(itaxs_in == 1) then  ! energ
        do iz = 1,nz
        do iy = 1,ny
        do ix = 1,nx
        do ip = 1,np

          tr0_sum = 0.0d0
          do ie = 1,ne
            tr0_sum = tr0_sum + tr0(ip,ie,icf(ix,iy,iz)) / maxcas
          end do
          tr_sum(ip,1,icf_sum(ix,iy,iz),1) =
     &           tr_sum(ip,1,icf_sum(ix,iy,iz),1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,1,icf_sum(ix,iy,iz),2) =
     %             tr_sum(ip,1,icf_sum(ix,iy,iz),2) + 1.0d0
           else
            tr_sum(ip,1,icf_sum(ix,iy,iz),2) =
     &           tr_sum(ip,1,icf_sum(ix,iy,iz),2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do
!
      else if(itaxs_in == 3) then  ! x
        do iz = 1,nz
        do iy = 1,ny
        do ie = 1,ne
        do ip = 1,np

          tr0_sum = 0.0d0
          do ix = 1,nx
            tr0_sum = tr0_sum + tr0(ip,ie,icf(ix,iy,iz)) / maxcas
          end do
          tr_sum(ip,ie,icf_sum(1,iy,iz),1) =
     &           tr_sum(ip,ie,icf_sum(1,iy,iz),1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,icf_sum(1,iy,iz),2) =
     %             tr_sum(ip,ie,icf_sum(1,iy,iz),2) + 1.0d0
           else
            tr_sum(ip,ie,icf_sum(1,iy,iz),2) =
     &           tr_sum(ip,ie,icf_sum(1,iy,iz),2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do

      else if(itaxs_in == 4) then  ! y
        do iz = 1,nz
        do ix = 1,nx
        do ie = 1,ne
        do ip = 1,np

          tr0_sum = 0.0d0
          do iy = 1,ny
            tr0_sum = tr0_sum + tr0(ip,ie,icf(ix,iy,iz)) / maxcas
          end do
          tr_sum(ip,ie,icf_sum(ix,1,iz),1) =
     &           tr_sum(ip,ie,icf_sum(ix,1,iz),1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,icf_sum(ix,1,iz),2) =
     %             tr_sum(ip,ie,icf_sum(ix,1,iz),2) + 1.0d0
           else
            tr_sum(ip,ie,icf_sum(ix,1,iz),2) =
     &           tr_sum(ip,ie,icf_sum(ix,1,iz),2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do

      else if(itaxs_in == 5) then  ! z
        do iy = 1,ny
        do ix = 1,nx
        do ie = 1,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do iz = 1,nz
            tr0_sum = tr0_sum + tr0(ip,ie,icf(ix,iy,iz)) / maxcas
          end do
          tr_sum(ip,ie,icf_sum(ix,iy,1),1) =
     &           tr_sum(ip,ie,icf_sum(ix,iy,1),1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,icf_sum(ix,iy,1),2) =
     %             tr_sum(ip,ie,icf_sum(ix,iy,1),2) + 1.0d0
           else
            tr_sum(ip,ie,icf_sum(ix,iy,1),2) =
     &           tr_sum(ip,ie,icf_sum(ix,iy,1),2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do


       end if
       return
       end


************************************************************************
*                                                                      *
      subroutine pletxyz_sumover_stdev(mode,m,ip,ie,ix,iy,iz,
     &                fact_in,ew,vl,ew_sum,vl_x,vl_y,vl_z)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

       if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

       else
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax):)
       endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/vl/ew
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 3 .and. ix == 1) then
             sum_fact = sum_fact * vl / vl_x
          else if(itaxs(m,iax) == 4 .and. iy == 1) then
             sum_fact = sum_fact * vl / vl_y
          else if(itaxs(m,iax) == 5 .and. iz == 1) then
             sum_fact = sum_fact * vl / vl_z
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pletxyz_sumover_stdev_sub(mode,m,sum_fact,
     &          ip,ie,ix,iy,iz,
     &         itpan_sum(m,iax),itenm_sum(m,iax),itxnm_sum(m,iax),
     &         itynm_sum(m,iax),itznm_sum(m,iax),tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pletxyz_sumover_stdev_ntf(mode,m,ntf,ip,ie,ix,iy,iz,
     &                fact_in,ew,vl,ew_sum,vl_x,vl_y,vl_z)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

       if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM_NTF(tr_sum,m,ntf,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM_NTF(tr_sum,m,ntf,iax)
C for nonshared_tally option
!$       end if

       else
          ntfbase = mtalsize_sum(m) * (ntf-1)
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax)+ntfbase:)
       endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/vl/ew
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 3 .and. ix == 1) then
             sum_fact = sum_fact * vl / vl_x
          else if(itaxs(m,iax) == 4 .and. iy == 1) then
             sum_fact = sum_fact * vl / vl_y
          else if(itaxs(m,iax) == 5 .and. iz == 1) then
             sum_fact = sum_fact * vl / vl_z
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pletxyz_sumover_stdev_sub(mode,m,sum_fact,
     &          ip,ie,ix,iy,iz,
     &         itpan_sum(m,iax),itenm_sum(m,iax),itxnm_sum(m,iax),
     &         itynm_sum(m,iax),itznm_sum(m,iax),tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pletxyz_sumover_stdev_sub(mode,m,sum_fact,
     &                   ip,ie,ix,iy,iz,
     &                   np_sum,ne_sum,nx_sum,ny_sum,nz_sum,
     &                   tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension tr_sum(np_sum,ne_sum,nx_sum*ny_sum*nz_sum,2)

      icf_sum(ix,iy,iz) = ix + ( iy - 1 ) * nx_sum
     &                   + ( iz - 1 ) * nx_sum * ny_sum

      if(tr_sum(ip,ie,icf_sum(ix,iy,iz),1) > 0.0) then
         if(mode == 0) then
                  call calc_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie,icf_sum(ix,iy,iz),1),
     &                            tr_sum(ip,ie,icf_sum(ix,iy,iz),2),
     &                            sum_fact)
         else
                  sum_fact_r = 1.0d0 / sum_fact
                  call invert_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie,icf_sum(ix,iy,iz),1),
     &                            tr_sum(ip,ie,icf_sum(ix,iy,iz),2),
     &                            sum_fact_r)
         endif
                  tr_sum(ip,ie,icf_sum(ix,iy,iz),1) = Xa
                  tr_sum(ip,ie,icf_sum(ix,iy,iz),2) = sigx

      else

        tr_sum(ip,ie,icf_sum(ix,iy,iz),2) = 0.0

      end if

      return
      end

************************************************************************
*                                                                      *
      subroutine  pletxyz_sumover_getput(mode,m,iax,
     &    npstepi,nestepi,nxstepi,nystepi,nzstepi,
     &    ipi,iei,ixi,iyi,izi,maxtott,tott_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      real(8) :: tott_sum(maxtott,2)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

      real(8),pointer :: tr_sum(:)

      real(8),allocatable :: tott_in(:,:)
      character :: chin*200


      if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

      call pletxyz_sumover_getput_sub(mode,
     &    npstepi,nestepi,nxstepi,nystepi,nzstepi,
     &    ipi,iei,ixi,iyi,izi,maxtott,tott_sum,
     &    itpan_sum(m,iax),itenm_sum(m,iax),itxnm_sum(m,iax),
     &    itynm_sum(m,iax),itznm_sum(m,iax),tr_sum)

      else
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

          nsame = npstepi * nestepi * nxstepi *nystepi * nzstepi
          allocate (tott_in(nsame,2))

          read(mode,'(a)') chin
          read(mode,'(26x,1000(1pe13.4,0pf8.4))')
     &    (tott_in(i,1),tott_in(i,2),i=1,nsame)

          call pletxyz_sumover_getput_sub(mode,
     &    npstepi,nestepi,nxstepi,nystepi,nzstepi,
     &    ipi,iei,ixi,iyi,izi,nsame,tott_in,
     &    itpan_sum(m,iax),itenm_sum(m,iax),itxnm_sum(m,iax),
     &    itynm_sum(m,iax),itznm_sum(m,iax),tr_sum)

          deallocate (tott_in)

      endif
      return
      end

************************************************************************
*                                                                      *
      subroutine pletxyz_sumover_getput_sub(mode,
     &    npstepi,nestepi,nxstepi,nystepi,nzstepi,
     &    ipi,iei,ixi,iyi,izi,maxtott,tott_sum,
     &    np_sum,ne_sum,nx_sum,ny_sum,nz_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(np_sum,ne_sum,nx_sum*ny_sum*nz_sum,2)

      real(8) :: tott_sum(maxtott,2)

      icf_sum(ix,iy,iz) = ix + ( iy - 1 ) * nx_sum
     &                   + ( iz - 1 ) * nx_sum * ny_sum

        i = 0
        do izloop=1,nzstepi
          do iyloop=1,nystepi
            do ixloop=1,nxstepi
              do ieloop=1,nestepi
                do iploop=1,npstepi
                  i = i + 1
                  do k=1,2
                    if(mode == 0) then
                      tott_sum(i,k) =
     &                tr_sum(ipi+iploop-1,iei+ieloop-1,
     &              icf_sum(ixi+ixloop-1,iyi+iyloop-1,izi+izloop-1),k)
                   else
                     tr_sum(ipi+iploop-1,iei+ieloop-1,
     &              icf_sum(ixi+ixloop-1,iyi+iyloop-1,izi+izloop-1),k)
     &               = tott_sum(i,k)
                   endif
                  enddo
                end do
              end do
            end do
          end do
        end do

      return
      end

************************************************************************
*                                                                      *
      subroutine tdepstreg_sumover(m,maxcas,
     &                   np,  ne, nr,  nt, tr0x)
*     tr_sum(np,0:ne,nr,nt,2)                                          *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,0:ne,nr,nt)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
        if(n_tr_sum > 0) then

          call tdepstreg_sumover_sub(maxcas,itaxs(m,iax),
     &      np,  ne, nr, nt, tr0x,
     &      itpan_sum(m,iax),itenm_sum(m,iax),
     &      itrgn_sum(m,iax),ittnm_sum(m,iax),
     &      tr_sum)

        endif

      enddo

      return
      end


************************************************************************
*                                                                      *
      subroutine tdepstreg_sumover_sub(maxcas_in,itaxs_in,
     &           np,  ne, nr, nt, tr0,
     &           np_sum,  ne_sum, nr_sum, nt_sum,
     &           tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,0:ne,nr,nt)
      dimension   tr_sum(np_sum,0:ne_sum,nr_sum,nt_sum,2)

      maxcas = maxcas_in
      if(maxcas_in == 0) then
         maxcas = 1
      endif

      if(itaxs_in == 1) then  ! energ
        do it = 1,nt
        do ir = 1,nr
        do ip = 1,np

          tr0_sum = 0.0d0
          tr_sum(ip,0,ir,it,1) = tr_sum(ip,0,ir,it,1) +
     &                         tr0(ip,0,ir,it) / maxcas
          if(maxcas_in == 0) then
            tr_sum(ip,0,ir,it,2) = tr_sum(ip,0,ir,it,2) + 1.0d0
          else
            tr_sum(ip,0,ir,it,2) = tr_sum(ip,0,ir,it,2) +
     &           (tr0(ip,0,ir,it) / maxcas) ** 2
          endif

          tr0_sum = 0.0d0
          do ie = 1,ne
            tr0_sum = tr0_sum + tr0(ip,ie,ir,it) / maxcas
          end do
          tr_sum(ip,1,ir,it,1) =
     &           tr_sum(ip,1,ir,it,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,1,ir,it,2) = tr_sum(ip,1,ir,it,2) + 1.0d0
           else
            tr_sum(ip,1,ir,it,2) =
     &           tr_sum(ip,1,ir,it,2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
!

      elseif(itaxs_in == 2) then    ! r
        do it = 1,nt
        do ie = 0,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do ir = 1,nr
            tr0_sum = tr0_sum + tr0(ip,ie,ir,it) / maxcas
          end do
          tr_sum(ip,ie,1,it,1) =
     &           tr_sum(ip,ie,1,it,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,1,it,2) = tr_sum(ip,ie,1,it,2) + 1.0d0
          else
            tr_sum(ip,ie,1,it,2) =
     &           tr_sum(ip,ie,1,it,2) + tr0_sum ** 2
          endif
        end do
        end do
        end do

      elseif(itaxs_in == 11) then   ! time
        do ir = 1,nr
        do ie = 0,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do it = 1,nt
            tr0_sum = tr0_sum + tr0(ip,ie,ir,it) / maxcas
          end do
          tr_sum(ip,ie,ir,1,1) =
     &           tr_sum(ip,ie,ir,1,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,ir,1,2) = tr_sum(ip,ie,ir,1,2) + 1.0d0
          else
            tr_sum(ip,ie,ir,1,2) =
     &           tr_sum(ip,ie,ir,1,2) + tr0_sum ** 2
          endif
        end do
        end do
        end do

       end if
       return
       end


************************************************************************
*                                                                      *
      subroutine pdepstreg_sumover_stdev(mode,m,ip,ie,ir,it,
     &                ne_s,
     &                fact_in,cfac,tw,vl,tw_sum,vl_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

        if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
       else
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax):)
       endif

        iei = ie
        if(n_tr_sum > 0) then
          sum_fact = fact_in/vl/tw
          if(itaxs(m,iax) == 1 .and. ie == ne_s) then
             iei = 1
          else if(itaxs(m,iax) == 2 .and. ir == 1) then
             sum_fact = sum_fact * vl / vl_sum
          else if(itaxs(m,iax) == 11 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pdepstreg_sumover_stdev_sub(mode,m,sum_fact,cfac,
     &         ip,iei,ir,it,
     &         itpan_sum(m,iax),itenm_sum(m,iax),itrgn_sum(m,iax),
     &         ittnm_sum(m,iax),
     &         tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pdepstreg_sumover_stdev_ntf(mode,m,ntf,ip,ie,ir,it,
     &                ne_s,
     &                fact_in,cfac,tw,vl,tw_sum,vl_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
