     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

        if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM_NTF(tr_sum,m,ntf,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM_NTF(tr_sum,m,ntf,iax)
C for nonshared_tally option
!$       end if
       else
          ntfbase = mtalsize_sum(m) * (ntf-1)
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax)+ntfbase:)
       endif

        iei = ie
        if(n_tr_sum > 0) then
          sum_fact = fact_in/vl/tw
          if(itaxs(m,iax) == 1 .and. ie == ne_s) then
             iei = 1
          else if(itaxs(m,iax) == 2 .and. ir == 1) then
             sum_fact = sum_fact * vl / vl_sum
          else if(itaxs(m,iax) == 11 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pdepstreg_sumover_stdev_sub(mode,m,sum_fact,cfac,
     &         ip,iei,ir,it,
     &         itpan_sum(m,iax),itenm_sum(m,iax),itrgn_sum(m,iax),
     &         ittnm_sum(m,iax),
     &         tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pdepstreg_sumover_stdev_sub(mode,m,sum_fact,cfac,
     &                   ip,ie,ir,it,
     &                   np_sum,ne_sum,nr_sum,nt_sum,
     &                   tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension tr_sum(np_sum,0:ne_sum,nr_sum,nt_sum,2)

      if(tr_sum(ip,ie,ir,it,1) > 0.0) then

          if(mode == 0) then
                  call calc_deposit_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie,ir,it,1),
     &                            tr_sum(ip,ie,ir,it,2),
     &                            sum_fact,ip)

                  tr_sum(ip,ie,ir,it,1) = cfac*Xa
                  tr_sum(ip,ie,ir,it,2) = sigx

          else
                  sum_fact_r = 1.0d0  / sum_fact / cfac
                  call invert_deposit_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie,ir,it,1),
     &                            tr_sum(ip,ie,ir,it,2),
     &                            sum_fact_r,ip)

                  tr_sum(ip,ie,ir,it,1) = Xa
                  tr_sum(ip,ie,ir,it,2) = sigx

          endif
      else

        tr_sum(ip,ie,ir,it,2) = 0.0

      end if

      return
      end

************************************************************************
*                                                                      *
      subroutine  pdepstreg_sumover_getput(mode,m,iax,
     &    npstepi,nestepi,nrstepi,ntstepi,
     &    ipi,iei,iri,iti,maxtott,tott_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      real(8) :: tott_sum(maxtott,2)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

      real(8),pointer :: tr_sum(:)

      real(8),allocatable :: tott_in(:,:)
      character :: chin*200

       if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

          call pdepstreg_sumover_getput_sub(mode,
     &    npstepi,nestepi,nrstepi,ntstepi,
     &    ipi,iei,iri,iti,maxtott,tott_sum,
     &    itpan_sum(m,iax),itenm_sum(m,iax),itrgn_sum(m,iax),
     &    ittnm_sum(m,iax),
     &    tr_sum)

      else
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

          nsame = npstepi * nestepi * nrstepi * ntstepi
          allocate (tott_in(nsame,2))

          read(mode,'(a)') chin
          read(mode,'(26x,1000(1pe13.4,0pf8.4))')
     &    (tott_in(i,1),tott_in(i,2),i=1,nsame)

          call pdepstreg_sumover_getput_sub(mode,
     &    npstepi,nestepi,nrstepi,ntstepi,
     &    ipi,iei,iri,iti,nsame,tott_in,
     &    itpan_sum(m,iax),itenm_sum(m,iax),itrgn_sum(m,iax),
     &    ittnm_sum(m,iax),
     &    tr_sum)

         deallocate (tott_in)

      endif
      return
      end

************************************************************************
*                                                                      *
      subroutine pdepstreg_sumover_getput_sub(mode,
     &    npstepi,nestepi,nrstepi,ntstepi,
     &    ipi,iei,iri,iti,maxtott,tott_sum,
     &    np_sum,ne_sum,nr_sum,nt_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(np_sum,0:ne_sum,nr_sum,nt_sum,2)

      real(8) :: tott_sum(maxtott,2)

        i = 0
           do itloop=1,ntstepi
            do irloop=1,nrstepi
              do ieloop=1,nestepi
                do iploop=1,npstepi
                  i = i + 1
                  do k=1,2
                    if(mode == 0) then
                      tott_sum(i,k) =
     &                tr_sum(ipi+iploop-1,iei+ieloop-1,iri+irloop-1,
     &                iti+itloop-1,k)
                    else
                      tr_sum(ipi+iploop-1,iei+ieloop-1,iri+irloop-1,
     &                iti+itloop-1,k)
     %                = tott_sum(i,k)
                    endif
                  enddo
                end do
              end do
            end do
          end do

      return
      end


************************************************************************
*                                                                      *
      subroutine tdepstrz_sumover(m,maxcas,
     &                   np,  ne, nt, nr,  nz, tr0x)
*     tr_sum(np,0:ne,nt,nr,nz,2)                                          *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,0:ne,nt,nr,nz)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
        if(n_tr_sum > 0) then

          call tdepstrz_sumover_sub(maxcas,itaxs(m,iax),
     &      np,  ne, nt, nr, nz, tr0x,
     &      itpan_sum(m,iax),itenm_sum(m,iax),
     &      ittnm_sum(m,iax),itrnm_sum(m,iax),
     &      itznm_sum(m,iax),
     &      tr_sum)

        endif

      enddo

      return
      end


************************************************************************
*                                                                      *
      subroutine tdepstrz_sumover_sub(maxcas_in,itaxs_in,
     &           np,  ne, nt, nr, nz, tr0,
     &           np_sum,  ne_sum, nt_sum, nr_sum, nz_sum,
     &           tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,0:ne,nt,nr,nz)
      dimension   tr_sum(np_sum,0:ne_sum,nt_sum,nr_sum,nz_sum,2)

      maxcas = maxcas_in
      if(maxcas_in == 0) then
         maxcas = 1
      endif

      if(itaxs_in == 1) then  ! energ
        do iz = 1,nz
        do ir = 1,nr
        do it = 1,nt
        do ip = 1,np

          tr0_sum = 0.0d0
          tr_sum(ip,0,it,ir,iz,1) = tr_sum(ip,0,it,ir,iz,1) +
     &                         tr0(ip,0,it,ir,iz) / maxcas
          if(maxcas_in == 0) then
            tr_sum(ip,0,it,ir,iz,2) = tr_sum(ip,0,it,ir,iz,2) + 1.0d0
          else
            tr_sum(ip,0,it,ir,iz,2) = tr_sum(ip,0,it,ir,iz,2) +
     &           (tr0(ip,0,it,ir,iz) / maxcas) ** 2
          endif

          tr0_sum = 0.0d0
          do ie = 1,ne
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,iz) / maxcas
          end do
          tr_sum(ip,1,it,ir,iz,1) =
     &           tr_sum(ip,1,it,ir,iz,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,1,it,ir,iz,2) = tr_sum(ip,1,it,ir,iz,2) + 1.0d0
           else
            tr_sum(ip,1,it,ir,iz,2) =
     &           tr_sum(ip,1,it,ir,iz,2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do
!
      elseif(itaxs_in == 5) then    ! z
        do ir = 1,nr
        do it = 1,nt
        do ie = 0,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do iz = 1,nz
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,iz) / maxcas
          end do
          tr_sum(ip,ie,it,ir,1,1) =
     &           tr_sum(ip,ie,it,ir,1,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,it,ir,1,2) = tr_sum(ip,ie,it,ir,1,2) + 1.0d0
          else
            tr_sum(ip,ie,it,ir,1,2) =
     &           tr_sum(ip,ie,it,ir,1,2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 6) then    ! r
        do iz = 1,nz
        do it = 1,nt
        do ie = 0,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do ir = 1,nr
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,iz) / maxcas
          end do
          tr_sum(ip,ie,it,1,iz,1) =
     &           tr_sum(ip,ie,it,1,iz,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,it,1,iz,2) = tr_sum(ip,ie,it,1,iz,2) + 1.0d0
          else
            tr_sum(ip,ie,it,1,iz,2) =
     &           tr_sum(ip,ie,it,1,iz,2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 11) then   ! time
        do iz = 1,nz
        do ir = 1,nr
        do ie = 0,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do it = 1,nt
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,iz) / maxcas
          end do
          tr_sum(ip,ie,1,ir,iz,1) =
     &           tr_sum(ip,ie,1,ir,iz,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,1,ir,iz,2) = tr_sum(ip,ie,1,ir,iz,2) + 1.0d0
          else
            tr_sum(ip,ie,1,ir,iz,2) =
     &           tr_sum(ip,ie,1,ir,iz,2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do

       end if
       return
       end

************************************************************************
*                                                                      *
      subroutine pdepstrz_sumover_stdev(mode,m,ip,ie,it,ir,iz,
     &                ne_s,
     &                fact_in,cfac,tw,vl,tw_sum,vl_r,vl_z)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

       if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
       else
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax):)
       endif

        iei = ie
        if(n_tr_sum > 0) then
           sum_fact = fact_in/vl/tw
          if(itaxs(m,iax) == 1 .and. ie == ne_s) then
             iei = 1
          else if(itaxs(m,iax) == 5 .and. iz == 1) then
             sum_fact = sum_fact * vl / vl_z
          else if(itaxs(m,iax) == 6 .and. ir == 1) then
             sum_fact = sum_fact * vl / vl_r
          else if(itaxs(m,iax) == 11 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pdepstrz_sumover_stdev_sub(mode,m,sum_fact,cfac,
     &         ip,iei,it,ir,iz,
     &         itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &         itrnm_sum(m,iax),itznm_sum(m,iax),
     &         tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pdepstrz_sumover_stdev_ntf(mode,m,ntf,ip,ie,it,ir,iz,
     &                ne_s,
     &                fact_in,cfac,tw,vl,tw_sum,vl_r,vl_z)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

       if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM_NTF(tr_sum,m,ntf,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM_NTF(tr_sum,m,ntf,iax)
C for nonshared_tally option
!$       end if
       else
          ntfbase = mtalsize_sum(m) * (ntf-1)
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax)+ntfbase:)
       endif

        iei = ie
        if(n_tr_sum > 0) then
           sum_fact = fact_in/vl/tw
          if(itaxs(m,iax) == 1 .and. ie == ne_s) then
             iei = 1
          else if(itaxs(m,iax) == 5 .and. iz == 1) then
             sum_fact = sum_fact * vl / vl_z
          else if(itaxs(m,iax) == 6 .and. ir == 1) then
             sum_fact = sum_fact * vl / vl_r
          else if(itaxs(m,iax) == 11 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pdepstrz_sumover_stdev_sub(mode,m,sum_fact,cfac,
     &         ip,iei,it,ir,iz,
     &         itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &         itrnm_sum(m,iax),itznm_sum(m,iax),
     &         tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pdepstrz_sumover_stdev_sub(mode,m,sum_fact,cfac,
     &                   ip,ie,it,ir,iz,
     &                   np_sum,ne_sum,nt_sum,nr_sum,nz_sum,
     &                   tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension tr_sum(np_sum,0:ne_sum,nt_sum,nr_sum,nz_sum,2)

      if(tr_sum(ip,ie,it,ir,iz,1) > 0.0) then

           if(mode == 0) then
                  call calc_deposit_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie,it,ir,iz,1),
     &                            tr_sum(ip,ie,it,ir,iz,2),
     &                            sum_fact,ip)

                  tr_sum(ip,ie,it,ir,iz,1) = cfac*Xa
                  tr_sum(ip,ie,it,ir,iz,2) = sigx
           else
                  sum_fact_r = 1.0d0 / sum_fact / cfac
                  call invert_deposit_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie,it,ir,iz,1),
     &                            tr_sum(ip,ie,it,ir,iz,2),
     &                            sum_fact_r,ip)

                  tr_sum(ip,ie,it,ir,iz,1) = Xa
                  tr_sum(ip,ie,it,ir,iz,2) = sigx
           endif

      else

        tr_sum(ip,ie,it,ir,iz,2) = 0.0

      end if

      return
      end

************************************************************************
*                                                                      *
      subroutine  pdepstrz_sumover_getput(mode,m,iax,
     &    npstepi,nestepi,ntstepi,nrstepi,nzstepi,
     &    ipi,iei,iti,iri,izi,maxtott,tott_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      real(8) :: tott_sum(maxtott,2)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

      real(8),pointer :: tr_sum(:)
      real(8),allocatable :: tott_in(:,:)
      character :: chin*200

      if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

      call pdepstrz_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nrstepi,nzstepi,
     &    ipi,iei,iti,iri,izi,maxtott,tott_sum,
     &    itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &    itrnm_sum(m,iax),itznm_sum(m,iax),
     &    tr_sum)

      else
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

          nsame = npstepi * nestepi * ntstepi * nrstepi * nzstepi
          allocate (tott_in(nsame,2))

          read(mode,'(a)') chin
          read(mode,'(26x,1000(1pe13.4,0pf8.4))')
     &    (tott_in(i,1),tott_in(i,2),i=1,nsame)


      call pdepstrz_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nrstepi,nzstepi,
     &    ipi,iei,iti,iri,izi,nsame,tott_in,
     &    itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &    itrnm_sum(m,iax),itznm_sum(m,iax),
     &    tr_sum)

          deallocate (tott_in)

      endif
      return
      end

************************************************************************
*                                                                      *
      subroutine pdepstrz_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nrstepi,nzstepi,
     &    ipi,iei,iti,iri,izi,maxtott,tott_sum,
     &    np_sum,ne_sum,nt_sum,nr_sum,nz_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(np_sum,0:ne_sum,nt_sum,nr_sum,nz_sum,2)

      real(8) :: tott_sum(maxtott,2)

        i = 0
        do izloop=1,nzstepi
          do irloop=1,nrstepi
            do itloop=1,ntstepi
              do ieloop=1,nestepi
                do iploop=1,npstepi
                  i = i + 1
                  do k=1,2
                    if(mode == 0) then
                      tott_sum(i,k) =
     &                tr_sum(ipi+iploop-1,iei+ieloop-1,iti+itloop-1,
     &                iri+irloop-1,izi+izloop-1,k)
                    else
                      tr_sum(ipi+iploop-1,iei+ieloop-1,iti+itloop-1,
     &                iri+irloop-1,izi+izloop-1,k)
     &                = tott_sum(i,k)
                    endif
                  enddo
                end do
              end do
            end do
          end do
        end do

      return
      end


************************************************************************
*                                                                      *
      subroutine tdepstxyz_sumover(m,maxcas,
     &                   np,  ne, nt, nx, ny, nz, tr0x)
*     tr_sum(np,0:ne,nt,nx,ny,nz,2)                                    *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,0:ne,nt,nx*ny*nz)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
        if(n_tr_sum > 0) then

          call tdepstxyz_sumover_sub(maxcas,itaxs(m,iax),
     &      np,  ne, nt, nx, ny, nz, tr0x,
     &      itpan_sum(m,iax),itenm_sum(m,iax),
     &      ittnm_sum(m,iax),itxnm_sum(m,iax),
     &      itynm_sum(m,iax),itznm_sum(m,iax),
     &      tr_sum)

        endif

      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine tdepstxyz_sumover_sub(maxcas_in,itaxs_in,
     &           np,  ne, nt, nx, ny, nz, tr0,
     &           np_sum,  ne_sum, nt_sum, nx_sum, ny_sum, nz_sum,
     &           tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,0:ne,nt,nx*ny*nz)
      dimension   tr_sum(np_sum,0:ne_sum,nt_sum,nx_sum*ny_sum*nz_sum,2)

      icf(ix,iy,iz) = ix + ( iy - 1 ) * nx + ( iz - 1 ) * nx * ny
      icf_sum(ix,iy,iz) = ix + ( iy - 1 ) * nx_sum
     &                  + ( iz - 1 ) * nx_sum * ny_sum

      maxcas = maxcas_in
      if(maxcas_in == 0) then
         maxcas = 1
      endif

      if(itaxs_in == 1) then  ! energ
        do iz = 1,nz
        do iy = 1,ny
        do ix = 1,nx
        do it = 1,nt
        do ip = 1,np

          tr0_sum = 0.0d0
          tr_sum(ip,0,it,icf_sum(ix,iy,iz),1) =
     &        tr_sum(ip,0,it,icf_sum(ix,iy,iz),1) +
     &                         tr0(ip,0,it,icf(ix,iy,iz)) / maxcas
          if(maxcas_in == 0) then
            tr_sum(ip,0,it,icf_sum(ix,iy,iz),2) =
     &                  tr_sum(ip,0,it,icf_sum(ix,iy,iz),2) + 1.0d0
          else
            tr_sum(ip,0,it,icf_sum(ix,iy,iz),2) =
     &            tr_sum(ip,0,it,icf_sum(ix,iy,iz),2) +
     &           (tr0(ip,0,it,icf(ix,iy,iz)) / maxcas) ** 2
          endif

          tr0_sum = 0.0d0
          do ie = 1,ne
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ix,iy,iz)) / maxcas
          end do
          tr_sum(ip,1,it,icf_sum(ix,iy,iz),1) =
     &           tr_sum(ip,1,it,icf_sum(ix,iy,iz),1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,1,it,icf_sum(ix,iy,iz),2) =
     &          tr_sum(ip,1,it,icf_sum(ix,iy,iz),2) + 1.0d0
           else
            tr_sum(ip,1,it,icf_sum(ix,iy,iz),2) =
     &           tr_sum(ip,1,it,icf_sum(ix,iy,iz),2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do
        end do
!
      elseif(itaxs_in == 3) then    ! x
        do iz = 1,nz
        do iy = 1,ny
        do it = 1,nt
        do ie = 0,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do ix = 1,nx
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ix,iy,iz)) / maxcas
          end do
          tr_sum(ip,ie,it,icf_sum(1,iy,iz),1) =
     &           tr_sum(ip,ie,it,icf_sum(1,iy,iz),1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,it,icf_sum(1,iy,iz),2) =
     &          tr_sum(ip,ie,it,icf_sum(1,iy,iz),2) + 1.0d0
           else
            tr_sum(ip,ie,it,icf_sum(1,iy,iz),2) =
     &           tr_sum(ip,ie,it,icf_sum(1,iy,iz),2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 4) then    ! y
        do iz = 1,nz
        do ix = 1,nx
        do it = 1,nt
        do ie = 0,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do iy = 1,ny
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ix,iy,iz)) / maxcas
          end do
          tr_sum(ip,ie,it,icf_sum(ix,1,iz),1) =
     &           tr_sum(ip,ie,it,icf_sum(ix,1,iz),1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,it,icf_sum(ix,1,iz),2) =
     &          tr_sum(ip,ie,it,icf_sum(ix,1,iz),2) + 1.0d0
           else
            tr_sum(ip,ie,it,icf_sum(ix,1,iz),2) =
     &           tr_sum(ip,ie,it,icf_sum(ix,1,iz),2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 5) then    ! z
        do iy = 1,ny
        do ix = 1,nx
        do it = 1,nt
        do ie = 0,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do iz = 1,nz
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ix,iy,iz)) / maxcas
          end do
          tr_sum(ip,ie,it,icf_sum(ix,iy,1),1) =
     &           tr_sum(ip,ie,it,icf_sum(ix,iy,1),1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,it,icf_sum(ix,iy,1),2) =
     &          tr_sum(ip,ie,it,icf_sum(ix,iy,1),2) + 1.0d0
           else
            tr_sum(ip,ie,it,icf_sum(ix,iy,1),2) =
     &           tr_sum(ip,ie,it,icf_sum(ix,iy,1),2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 11) then    ! t
        do iz = 1,nz
        do iy = 1,ny
        do ix = 1,nx
        do ie = 0,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do it = 1,nt
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ix,iy,iz)) / maxcas
          end do
          tr_sum(ip,ie,1,icf_sum(ix,iy,iz),1) =
     &           tr_sum(ip,ie,1,icf_sum(ix,iy,iz),1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,1,icf_sum(ix,iy,iz),2) =
     &          tr_sum(ip,ie,1,icf_sum(ix,iy,iz),2) + 1.0d0
           else
            tr_sum(ip,ie,1,icf_sum(ix,iy,iz),2) =
     &           tr_sum(ip,ie,1,icf_sum(ix,iy,iz),2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do
        end do

       end if
       return
       end

************************************************************************
*                                                                      *
      subroutine pdepstxyz_sumover_stdev(mode,m,ip,ie,it,ix,iy,iz,
     &                ne_s,
     &                fact_in,cfac,tw,vl,tw_sum,vl_x,vl_y,vl_z)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

        if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
        else
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax):)
        endif

        iei = ie
        if(n_tr_sum > 0) then
          sum_fact = fact_in/vl/tw
          if(itaxs(m,iax) == 1 .and. ie == ne_s) then
             iei = 1
          else if(itaxs(m,iax) == 3 .and. ix == 1) then
             sum_fact = sum_fact * vl /vl_x
          else if(itaxs(m,iax) == 4 .and. iy == 1) then
             sum_fact = sum_fact * vl /vl_y
          else if(itaxs(m,iax) == 5 .and. iz == 1) then
             sum_fact = sum_fact * vl /vl_z
          else if(itaxs(m,iax) == 11 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pdepstxyz_sumover_stdev_sub(mode,m,sum_fact,cfac,
     &         ip,iei,it,ix,iy,iz,
     &         itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &         itxnm_sum(m,iax),itynm_sum(m,iax),itznm_sum(m,iax),
     &         tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pdepstxyz_sumover_stdev_ntf(mode,m,ntf,
     &                ip,ie,it,ix,iy,iz,
     &                ne_s,
     &                fact_in,cfac,tw,vl,tw_sum,vl_x,vl_y,vl_z)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

        if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM_NTF(tr_sum,m,ntf,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM_NTF(tr_sum,m,ntf,iax)
C for nonshared_tally option
!$       end if
        else
          ntfbase = mtalsize_sum(m) * (ntf-1)
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax)+ntfbase:)
        endif

        iei = ie
        if(n_tr_sum > 0) then
          sum_fact = fact_in/vl/tw
          if(itaxs(m,iax) == 1 .and. ie == ne_s) then
             iei = 1
          else if(itaxs(m,iax) == 3 .and. ix == 1) then
             sum_fact = sum_fact * vl /vl_x
          else if(itaxs(m,iax) == 4 .and. iy == 1) then
             sum_fact = sum_fact * vl /vl_y
          else if(itaxs(m,iax) == 5 .and. iz == 1) then
             sum_fact = sum_fact * vl /vl_z
          else if(itaxs(m,iax) == 11 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pdepstxyz_sumover_stdev_sub(mode,m,sum_fact,cfac,
     &         ip,iei,it,ix,iy,iz,
     &         itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &         itxnm_sum(m,iax),itynm_sum(m,iax),itznm_sum(m,iax),
     &         tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pdepstxyz_sumover_stdev_sub(mode,m,sum_fact,cfac,
     &                   ip,ie,it,ix,iy,iz,
     &                   np_sum,ne_sum,nt_sum,nx_sum,ny_sum,nz_sum,
     &                   tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension tr_sum(np_sum,0:ne_sum,nt_sum,nx_sum*ny_sum*nz_sum,2)

      icf_sum(ix,iy,iz) = ix + ( iy - 1 ) * nx_sum
     &                  + ( iz - 1 ) * nx_sum * ny_sum

      if(tr_sum(ip,ie,it,icf_sum(ix,iy,iz),1) > 0.0) then
          if(mode == 0) then
                  call calc_deposit_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie,it,icf_sum(ix,iy,iz),1),
     &                            tr_sum(ip,ie,it,icf_sum(ix,iy,iz),2),
     &                            sum_fact,ip)

                  tr_sum(ip,ie,it,icf_sum(ix,iy,iz),1) = cfac*Xa
                  tr_sum(ip,ie,it,icf_sum(ix,iy,iz),2) = sigx
          else
                  sum_fact_r = 1.0d0 / sum_fact / cfac
                  call invert_deposit_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie,it,icf_sum(ix,iy,iz),1),
     &                            tr_sum(ip,ie,it,icf_sum(ix,iy,iz),2),
     &                            sum_fact_r,ip)

                  tr_sum(ip,ie,it,icf_sum(ix,iy,iz),1) = Xa
                  tr_sum(ip,ie,it,icf_sum(ix,iy,iz),2) = sigx
          endif

      else

        tr_sum(ip,ie,it,icf_sum(ix,iy,iz),2) = 0.0

      end if

      return
      end

************************************************************************
*                                                                      *
      subroutine  pdepstxyz_sumover_getput(mode,m,iax,
     &    npstepi,nestepi,ntstepi,nxstepi,nystepi,nzstepi,
     &    ipi,iei,iti,ixi,iyi,izi,maxtott,tott_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      real(8) :: tott_sum(maxtott,2)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

      real(8),pointer :: tr_sum(:)
      real(8),allocatable :: tott_in(:,:)
      character :: chin*200

      if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

      call pdepstxyz_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nxstepi,nystepi,nzstepi,
     &    ipi,iei,iti,ixi,iyi,izi,maxtott,tott_sum,
     &    itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &    itxnm_sum(m,iax),itynm_sum(m,iax),itznm_sum(m,iax),
     &    tr_sum)

      else
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

          nsame = npstepi * nestepi * ntstepi * nxstepi * nystepi
     &          * nzstepi
          allocate (tott_in(nsame,2))

          read(mode,'(a)') chin
          read(mode,'(26x,1000(1pe13.4,0pf8.4))')
     &    (tott_in(i,1),tott_in(i,2),i=1,nsame)

          call pdepstxyz_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nxstepi,nystepi,nzstepi,
     &    ipi,iei,iti,ixi,iyi,izi,nsame,tott_in,
     &    itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &    itxnm_sum(m,iax),itynm_sum(m,iax),itznm_sum(m,iax),
     &    tr_sum)

          deallocate (tott_in)

      endif

      return
      end

************************************************************************
*                                                                      *
      subroutine pdepstxyz_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nxstepi,nystepi,nzstepi,
     &    ipi,iei,iti,ixi,iyi,izi,maxtott,tott_sum,
     &    np_sum,ne_sum,nt_sum,nx_sum,ny_sum,nz_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(np_sum,0:ne_sum,nt_sum,nx_sum*ny_sum*nz_sum,2)

      real(8) :: tott_sum(maxtott,2)
      icf_sum(ix,iy,iz) = ix + ( iy - 1 ) * nx_sum
     &                  + ( iz - 1 ) * nx_sum * ny_sum

        i = 0
        do izloop=1,nzstepi
         do iyloop=1,nystepi
          do ixloop=1,nxstepi
            do itloop=1,ntstepi
              do ieloop=1,nestepi
                do iploop=1,npstepi
                  i = i + 1
                  do k=1,2
                   if(mode == 0) then
                    tott_sum(i,k) =
     &              tr_sum(ipi+iploop-1,iei+ieloop-1,iti+itloop-1,
     &              icf_sum(ixi+ixloop-1,iyi+iyloop-1,izi+izloop-1),k)
                   else
                    tr_sum(ipi+iploop-1,iei+ieloop-1,iti+itloop-1,
     &              icf_sum(ixi+ixloop-1,iyi+iyloop-1,izi+izloop-1),k)
     &              = tott_sum(i,k)
                   endif
                  enddo
                end do
              end do
            end do
          end do
        end do
       end do

      return
      end

************************************************************************
*                                                                      *
      subroutine tdpst2reg_sumover(m, maxcas,
     &                            np,  ne1, ne2, nt, tr0x)
*                                                                      *
************************************************************************
*      tdpst2regEVENT : maxcas_in = 0

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

      real(8) ::  tr0x(np,0:ne1,0:ne2,nt)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)


      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
        if(n_tr_sum > 0) then

          call tdpst2reg_sumover_sub(maxcas,itaxs(m,iax),
     &      np,  ne1, ne2, nt, tr0x,
     &      itpan_sum(m,iax),itenm_sum(m,iax),
     &      itenm2_sum(m,iax),ittnm_sum(m,iax),
     &      tr_sum)

        endif

      enddo

      return
      end


************************************************************************
*                                                                      *
      subroutine tdpst2reg_sumover_sub(maxcas_in,itaxs_in,
     &           np,  ne1, ne2, nt, tr0,
     &           np_sum,  ne1_sum, ne2_sum, nt_sum,
     &           tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      real(8) ::  tr0(np,0:ne1,0:ne2,nt)
      dimension   tr_sum(np_sum,0:ne1_sum,0:ne2_sum,nt_sum,2)

      maxcas = maxcas_in
      if(maxcas_in == 0) then
         maxcas = 1
      endif

      if(itaxs_in == 1) then  ! energ
        do it = 1,nt
        do ie2 = 0,ne2
        do ip = 1,np

          tr0_sum = 0.0d0
          tr_sum(ip,0,ie2,it,1) = tr_sum(ip,0,ie2,it,1) +
     &                         tr0(ip,0,ie2,it) / maxcas
          if(maxcas_in == 0) then
            tr_sum(ip,0,ie2,it,2) = tr_sum(ip,0,ie2,it,2) + 1.0d0
          else
            tr_sum(ip,0,ie2,it,2) = tr_sum(ip,0,ie2,it,2) +
     &           (tr0(ip,0,ie2,it) / maxcas) ** 2
          endif

          tr0_sum = 0.0d0
          do ie1 = 1,ne1
            tr0_sum = tr0_sum + tr0(ip,ie1,ie2,it) / maxcas
          end do
          tr_sum(ip,1,ie2,it,1) =
     &           tr_sum(ip,1,ie2,it,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,1,ie2,it,2) = tr_sum(ip,1,ie2,it,2) + 1.0d0
           else
            tr_sum(ip,1,ie2,it,2) =
     &           tr_sum(ip,1,ie2,it,2) + tr0_sum ** 2
          endif
        end do
        end do
        end do

      else if(itaxs_in == 2) then  ! energ2
        do it = 1,nt
        do ie1 = 0,ne1
        do ip = 1,np

          tr0_sum = 0.0d0
          tr_sum(ip,ie1,0,it,1) = tr_sum(ip,ie1,0,it,1) +
     &                         tr0(ip,ie1,0,it) / maxcas
          if(maxcas_in == 0) then
            tr_sum(ip,ie1,0,it,2) = tr_sum(ip,ie1,0,it,2) + 1.0d0
          else
            tr_sum(ip,ie1,0,it,2) = tr_sum(ip,ie1,0,it,2) +
     &           (tr0(ip,ie1,0,it) / maxcas) ** 2
          endif

          tr0_sum = 0.0d0
          do ie2 = 1,ne2
            tr0_sum = tr0_sum + tr0(ip,ie1,ie2,it) / maxcas
          end do
          tr_sum(ip,ie1,1,it,1) =
     &           tr_sum(ip,ie1,1,it,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie1,1,it,2) = tr_sum(ip,ie1,1,it,2) + 1.0d0
           else
            tr_sum(ip,ie1,1,it,2) =
     &           tr_sum(ip,ie1,1,it,2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
!
      else if(itaxs_in == 9) then  ! t
        do ie2 = 0,ne2
        do ie1 = 0,ne1
        do ip = 1,np

          tr0_sum = 0.0d0
         do it = 1,nt
            tr0_sum = tr0_sum + tr0(ip,ie1,ie2,it) / maxcas
          end do
          tr_sum(ip,ie1,ie2,1,1) =
     &           tr_sum(ip,ie1,ie2,1,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie1,ie2,1,2) = tr_sum(ip,ie1,ie2,1,2) + 1.0d0
           else
            tr_sum(ip,ie1,ie2,1,2) =
     &           tr_sum(ip,ie1,ie2,1,2) + tr0_sum ** 2
          endif
        end do
        end do
        end do

       end if
       return
       end

************************************************************************
*                                                                      *
      subroutine pdpst2reg_sumover_stdev(mode,m,ip,ie1,ie2,it,
     &                ne1_s,ne2_s,
     &                fact_in,cfac,tw,vl,tw_sum,vl_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

        if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
        else
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax):)
        endif

        ie1i = ie1
        ie2i = ie2
        if(n_tr_sum > 0) then
           sum_fact = fact_in/vl/tw
          if(itaxs(m,iax) == 1 .and. ie1 == ne1_s) then
             ie1i = 1
          else if(itaxs(m,iax) == 2 .and. ie2 == ne2_s) then
             ie2i = 1
          else if(itaxs(m,iax) == 9 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pdpst2reg_sumover_stdev_sub(mode,m,sum_fact,cfac,
     &         ip,ie1i,ie2i,it,
     &         itpan_sum(m,iax),itenm_sum(m,iax),itenm2_sum(m,iax),
     &         ittnm_sum(m,iax),
     &         tr_sum)
          endif

        endif
      enddo

      return
      end


************************************************************************
*                                                                      *
      subroutine pdpst2reg_sumover_stdev_ntf(mode,m,ntf,ip,ie1,ie2,it,
     &                ne1_s,ne2_s,
     &                fact_in,cfac,tw,vl,tw_sum,vl_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

        if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM_NTF(tr_sum,m,ntf,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM_NTF(tr_sum,m,ntf,iax)
C for nonshared_tally option
!$       end if
        else
          ntfbase = mtalsize_sum(m) * (ntf-1)
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax)+ntfbase:)
        endif

        ie1i = ie1
        ie2i = ie2
        if(n_tr_sum > 0) then
           sum_fact = fact_in/vl/tw
          if(itaxs(m,iax) == 1 .and. ie1 == ne1_s) then
             ie1i = 1
          else if(itaxs(m,iax) == 2 .and. ie2 == ne2_s) then
             ie2i = 1
          else if(itaxs(m,iax) == 9 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pdpst2reg_sumover_stdev_sub(mode,m,sum_fact,cfac,
     &         ip,ie1i,ie2i,it,
     &         itpan_sum(m,iax),itenm_sum(m,iax),itenm2_sum(m,iax),
     &         ittnm_sum(m,iax),
     &         tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pdpst2reg_sumover_stdev_sub(mode,m,sum_fact,cfac,
     &                   ip,ie1,ie2,it,
     &                   np_sum,ne1_sum,ne2_sum,nt_sum,
     &                   tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension tr_sum(np_sum,0:ne1_sum,0:ne2_sum,nt_sum,2)

      if(tr_sum(ip,ie1,ie2,it,1) > 0.0) then

         if(mode == 0) then
                  call calc_deposit_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie1,ie2,it,1),
     &                            tr_sum(ip,ie1,ie2,it,2),
     &                            sum_fact,ip)

                  tr_sum(ip,ie1,ie2,it,1) = cfac*Xa
                  tr_sum(ip,ie1,ie2,it,2) = sigx
         else
                  sum_fact_r = 1.0d0 / sum_fact / cfac
                  call invert_deposit_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie1,ie2,it,1),
     &                            tr_sum(ip,ie1,ie2,it,2),
     &                            sum_fact_r,ip)

                  tr_sum(ip,ie1,ie2,it,1) = Xa
                  tr_sum(ip,ie1,ie2,it,2) = sigx
         endif

      else

        tr_sum(ip,ie1,ie2,it,2) = 0.0

      end if

      return
      end

************************************************************************
*                                                                      *
      subroutine  pdpst2reg_sumover_getput(mode,m,iax,
     &    npstepi,ne1stepi,ne2stepi,ntstepi,
     &    ipi,ie1i,ie2i,iti,maxtott,tott_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      real(8) :: tott_sum(maxtott,2)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

      real(8),pointer :: tr_sum(:)
      real(8),allocatable :: tott_in(:,:)
      character :: chin*200

      if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

          call pdpst2reg_sumover_getput_sub(mode,
     &    npstepi,ne1stepi,ne2stepi,ntstepi,
     &    ipi,ie1i,ie2i,iti,maxtott,tott_sum,
     &    itpan_sum(m,iax),itenm_sum(m,iax),itenm2_sum(m,iax),
     &    ittnm_sum(m,iax),
     &    tr_sum)

       else
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

          nsame = npstepi * ne1stepi * ne2stepi * ntstepi
          allocate (tott_in(nsame,2))

          read(mode,'(a)') chin
          read(mode,'(26x,1000(1pe13.4,0pf8.4))')
     &    (tott_in(i,1),tott_in(i,2),i=1,nsame)


          call pdpst2reg_sumover_getput_sub(mode,
     &    npstepi,ne1stepi,ne2stepi,ntstepi,
     &    ipi,ie1i,ie2i,iti,nsame,tott_in,
     &    itpan_sum(m,iax),itenm_sum(m,iax),itenm2_sum(m,iax),
     &    ittnm_sum(m,iax),tr_sum)

          deallocate (tott_in)

      endif

      return
      end

************************************************************************
*                                                                      *
      subroutine pdpst2reg_sumover_getput_sub(mode,
     &    npstepi,ne1stepi,ne2stepi,ntstepi,
     &    ipi,ie1i,ie2i,iti,maxtott,tott_sum,
     &    np_sum,ne1_sum,ne2_sum,nt_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(np_sum,0:ne1_sum,0:ne2_sum,nt_sum,2)

      real(8) :: tott_sum(maxtott,2)

        i = 0
           do itloop=1,ntstepi
            do ie2loop=1,ne2stepi
              do ie1loop=1,ne1stepi
                do iploop=1,npstepi
                  i = i + 1
                  do k=1,2
                    if(mode == 0) then
                      tott_sum(i,k) =
     &                tr_sum(ipi+iploop-1,ie1i+ie1loop-1,ie2i+ie2loop-1,
     &                iti+itloop-1,k)
                    else
                      tr_sum(ipi+iploop-1,ie1i+ie1loop-1,ie2i+ie2loop-1,
     &                iti+itloop-1,k)
     &                = tott_sum(i,k)
                    endif
                  enddo
                end do
              end do
            end do
          end do

      return
      end

